const a={1:[["1","Adem, Şit, Enoş,"],["2","Kenan, Mahalalel, Yeret,"],["3","Hanok, Metuşelah, Lemek,"],["4","Noa, Sam, Ham, Yafet"],["5","Yafet'in oğulları: Gomer, Magog, Meday, Yâvan, Tuval, Meşek, Tiras."],["6","Gomer'in oğulları: Aşkenaz, Difat, Togarma."],["7","Yâvan'ın oğulları: Elişa, Tarşiş, Kittim, Rodanim."],["8","Ham'ın oğulları: Kûş, Misrayim, Pût, Kenan."],["9","Kûş'un oğulları: Seva, Havila, Savta, Raama, Savteka. Raama'nın oğulları: Şeva, Dedan."],["10","Kûş, Nimrod'un babası oldu. O yeryüzünde güçlü biri olmaya başladı."],["11","Misrayim Ludlular'ın, Anamlılar'ın, Lehavlılar'ın, Naftuhlular'ın,"],["12","Patruslular'ın, Filistliler'in ataları olan Kasluhlular'ın (Filistliler bunlardan geldi) ve Kaftorlular'ın atasıydı."],["13","Kenan ilk oğlu Sidon'un ve Hititler'in,"],["14","Yevuslular'ın, Amorlular'ın, Girgaşlılar'ın,"],["15","Hivliler'in, Arklılar'ın, Sinliler'in,"],["16","Arvatlılar'ın, Semarlılar'ın, Hamalılar'ın babasıydı."],["17","Sam'ın oğulları: Elam, ve Aşur, ve Arpakşad, ve Lud, ve Aram, ve Uts, ve Hul, ve Geter, ve Meşek."],["18","Arpakşad, Şelahın babası oldu, ve Şelah Everin babası oldu."],["19","Ever'e iki oğul doğdu; birinin adı Pelek'di; çünkü onun günlerinde yeryüzü bölündü; ve kardeşinin adı Yoktan idi."],["20","Yoktan, Almodad'ın, Şelef'in, Hazarmavet'in, Yerah'ın,"],["21","Hadoram'ın, Uzal'ın, Diklah'ın,"],["22","Eval'ın, Avimael'in, Şeva'nın,"],["23","Ofir, Havila ve Yovav'ın babası oldu. Bunların hepsi Yoktan'ın oğullarıydı."],["24","Şem, Arpakşad, Şela,"],["25","Ever, Pelek, Reu,"],["26","Seruk, Nahor, Terah,"],["27","Avram (Avraham da denilir)."],["28","Avraham'ın oğulları: İshak ve İşmael."],["29","Bunlar onların kuşaklarıdır: İşmael'in ilk oğlu Nevayot; sonra Kedar, Adbeel, Mivsam,"],["30","Mişma, Duma, Massa, Hadad, Tema,"],["31","Yetur, Nafiş ve Kedema. Bunlar İşmael'in oğullarıydı."],["32","Avraham'ın cariyesi Ketura'nın oğulları: Zimran, Yokşan, Medan, Midyan, Yişvak ve Şuah'ı doğurdu. Yokşan'ın oğulları: Şeva ve Dedan."],["33","Midyan'ın oğulları: Efa, Efer, Hanok, Avida ve Eldaa. Bunların hepsi Ketura'nın oğullarıydı."],["34","Avraham, İshak'ın babası oldu. İshak'ın oğulları: Esav ve İsrael."],["35","Esav'ın oğulları: Elifaz, Reuel, Yeuş, Yalam ve Korah."],["36","Elifez'in oğulları: Teman, Omar, Sefi, Gatam, Kenaz, Timna ve Amalek."],["37","Reuel'in oğulları: Nahat, Zerah, Şamma ve Mizza."],["38","Seir'in oğulları: Lotan, Şoval, Siveon, Ana, Dişon, Ezer ve Dişan."],["39","Lotan'ın oğulları: Hori ve Homam; Timna Lotan'ın kız kardeşiydi."],["40","Şoval'ın oğulları: Alian, Manahat, Eval, Şefi ve Onam. Siveon'un oğulları: Aya ve Ana."],["41","Anah'ın oğulları: Dişon. Dişon'un oğulları: Hamran, Eşvan, İtran ve Keran."],["42","Ezer'in oğulları: Bilhan, Zaavan ve Yaakan. Dişan'ın oğulları: Uts ve Aran."],["43","İsrael'in çocukları üzerinde hiçbir kral hüküm sürmeden önce, Edom ülkesinde hüküm süren krallar şunlardır: Beor oğlu Bela; ve kentinin adı Dinhabah idi."],["44","Bela öldü ve yerine Bosralı Zerah oğlu Yovav kral oldu."],["45","Yovav öldü ve yerine Temanlılar ülkesinden Huşam kral oldu."],["46","Huşam öldü ve yerine Moav kırlarında Midyan'ı vuran Bedad oğlu Hadad kral oldu; kentinin adı Avit idi."],["47","Hadad öldü ve yerine Masrekalı Samla kral oldu."],["48","Samla öldü ve yerine Irmak kıyısındaki Rehovotlu Şaul kral oldu."],["49","Şaul öldü ve yerine Akvor oğlu Baal Hanan kral oldu."],["50","Baal Hanan öldü ve yerine Hadad kral oldu; kentinin adı Pai idi. Karısının adı Mezahav kızı Matred'in kızı Mehetabel'di."],["51","Sonra Hadad öldü. Edom'un beyleri şunlardı: Bey Timna, Bey Aliah, Bey Yetet,"],["52","Bey Oholivama, Bey Ela, Bey Pinon,"],["53","Bey Kenaz, Bey Teman, Bey Mivsar,"],["54","Bey Magdiel ve Bey İram. Bunlar Edom'un beyleridir"]],2:[["1","İsrael'in oğulları şunlardır: Ruven, Şimon, Levi, Yahuda, İssakar, Zevulun,"],["2","Dan, Yosef, Benyamin, Naftali, Gad ve Aşer."],["3","Yahuda'nın oğulları: Er, Onan ve Şela. Bu üçü, Kenanlı Şua'nın kızından olan oğluydu. Yahuda'nın ilk oğlu olan Er, Yahve'nin gözünde kötüydü ve onu öldürdü."],["4","Gelini Tamar ona Peres ve Zerah'ı doğurdu. Yahuda'nın bütün oğulları beştir."],["5","Peres'in oğulları: Hetsron ve Hamul."],["6","Zera'nın oğulları: Zimri, Etan, Heman, Kalkol ve Dara; bunların hepsi beştir."],["7","Karmi'nin oğlu: Adanmış şeye karşı suç işleyerek İsrael'i sıkıntıya sokan Ahar."],["8","Etan'ın oğlu: Azarya."],["9","Hetsron'un kendisine doğan oğulları: Yerahmeel, Ram ve Keluva."],["10","Ram, Amminadav'ın babası oldu; Amminadav da Yahuda oğullarının beyi Nahşon'un babası oldu."],["11","Nahşon, Salma'nın babası oldu; Salma, Boaz'ın babası oldu."],["12","Boaz, Oved'in babası oldu; Oved de Yişay'ın babası oldu."],["13","Yişay, ilk oğlu Eliav'ın, ikinci oğlu Avinadav'ın, üçüncü oğlu Şimea'nın,"],["14","dördüncü oğlu Netanel'in, beşinci oğlu Radday'ın,"],["15","Altıncı oğlu Otsem'in ve yedinci oğlu David'in babası oldu."],["16","Kız kardeşleri ise Seruya ve Avigail'di. Seruya'nın oğulları: Avişay, Yoav ve Asahel, üçtü."],["17","Avigail, Amasa'yı doğurdu; Amasa'nın babası ise İşmaelli Yeter'di."],["18","Hetsron oğlu Kalev, karısı Azuvah'dan ve Yeriot'tan çocuk sahibi oldu. Bunlar kadının oğullarıydı: Yeşer, Şovav ve Ardon."],["19","Azuvah öldü ve Kalev, kendisine Hur'u doğuran Efrat'la evlendi."],["20","Hur, Uri'nin babası oldu ve Uri de Betsalel'in babası oldu."],["21","Daha sonra Hetsron, altmış yaşındayken Gilad'ın babası Makir'in kızının yanına girdi ve onu eş olarak aldı. Kadın ona Seguv'u doğurdu."],["22","Seguv, Gilad ülkesinde yirmi üç kenti olan Yair'in babası oldu."],["23","Geşur ve Aram, Yair'in kasabalarını, Kenat'ı ve köylerini, altmış kenti onlardan aldılar. Bunların hepsi Gilad'ın babası Makir'in oğullarıydı."],["24","Hetsron Kalev Efrata'da öldükten sonra, Hetsron'un karısı Aviya, ona Tekoa'nın babası Aşhur'u doğurdu."],["25","Hetsron'un ilk oğlu Yerahmeel'in oğulları, ilk oğlu Ram, Bunah, Oren, Otsem ve Ahiya'ydı."],["26","Yerahmeel'in başka bir karısı daha vardı; adı Atara'ydı. Onam'ın annesiydi."],["27","Yerahmeel'in ilk oğlu Ram'ın oğulları, Maats, Yamin ve Eker'di."],["28","Onam'ın oğulları, Şammay ve Yada'ydı. Şammay'ın oğulları, Nadav ve Avişar'dı."],["29","Avishur'un karısının adı Avihayil'di; kadın ona Ahvan ve Molid'i doğurdu."],["30","Nadav'ın oğulları, Seled ve Appaim'di; ama Seled çocuksuz öldü."],["31","Appaim'in oğlu, İşi. İşi'nin oğlu, Şeşan'dı. Şeşan'ın oğlu: Ahlay."],["32","Şammay'ın kardeşi Yada'nın oğulları: Yeter ve Yonatan; ve Yeter çocuksuz öldü."],["33","Yonatan'ın oğulları: Pelet ve Zaza. Bunlar Yerahmeel'in oğullarıydı."],["34","Şeşan'ın oğlu yoktu, yalnız kızları vardı. Şeşan'ın bir hizmetkârı vardı, Mısırlı, adı Yarha'ydı."],["35","Şeşan kızını hizmetkârı Yarha'ya eş olarak verdi; ve ona Attay'ı doğurdu."],["36","Attay, Natan'ın babası oldu ve Natan, Zavad'ın babası oldu."],["37","Zavad, Eflal'ın babası oldu ve Eflal, Oved'in babası oldu."],["38","Oved, Yehu'nun babası oldu ve Yehu, Azarya'nın babası oldu."],["39","Azarya, Heles'in babası oldu ve Heles, Eleasa'nın babası oldu."],["40","Elasa, Sismay'ın babası oldu ve Sismay, Şallum'un babası oldu."],["41","Şallum, Yekamya'nın babası oldu ve Yekamya, Elişama'nın babası oldu."],["42","Yerahmeel'in kardeşi Kalev'in oğulları, ilk oğlu Zif'in babası olan Meşa ve Hevron'un babası olan Mareşah'ın oğullarıydı."],["43","Hevron'un oğulları: Korah, Tappuah, Rekem ve Şema."],["44","Şema, Yorkeam'ın babası olan Raham'ın babası oldu. Rekem, Şammay'ın babası oldu."],["45","Şammay'ın oğlu Maon'du. Maon da Beyt Sur'un babasıydı."],["46","Kalev'in cariyesi Efa, Haran'ı, Motsa'yı ve Gazez'i doğurdu. Haran, Gazez'in babası oldu."],["47","Yahday'ın oğulları: Regem, Yotan, Geşan, Pelet, Efa ve Şaaf."],["48","Kalev'in cariyesi Maaka, Şeber ve Tirhana'yı doğurdu."],["49","Madmanna'nın babası Şaaf'ı, Makbena'nın babası Şeva'yı ve Gibea'nın babasını doğurdu; Kalev'in kızı da Aksa'ydı."],["50","Efrata'nın ilk oğlu Hur'un oğlu Kalev'in oğulları şunlardı: Kiryat Yearim'in babası Şoval,"],["51","Beytlehem'in babası Salma ve Beyt Gader'in babası Haref."],["52","Kiryat Yearim'in babası Şoval'ın oğulları vardı: Haroeh, Menuhot'un yarısı."],["53","Kiryat Yearim'in aileleri: İtriler, Putiler, Şumatlılar ve Mişralılar; bunlardan da Soralılar ve Eştaollular geldi."],["54","Salma'nın oğulları: Beytlehemliler, Netofalılar, Atrot Beyt Yoav ve Manahatlılar'ın yarısı, Sorlular."],["55","Yaves'te yaşayan yazıcı aileleri: Tiratlılar, Şimeatlılar ve Şukatlılar. Bunlar, Rekav evinin babası olan Hammat'tan gelen Kenliler'dir."]],3:[["1","Hevron'da David'e doğan oğulları şunlardır: İlk oğlu, Yizreelli Ahinoam'dan Amnon; ikincisi, Karmelli Avigail'den Daniel;"],["2","Üçüncüsü, Geşur Kralı Talmay'ın kızı Maaka'nın oğlu Avşalom; dördüncüsü, Hagit'in oğlu Adoniya;"],["3","Beşincisi, Avital'den Şefatya; altıncısı, karısı Egla'dan İtream."],["4","Hevron'da kendisine altı çocuk doğdu; ve orada yedi yıl altı ay hüküm sürdü. Yeruşalem'de otuz üç yıl hüküm sürdü."],["5","Ve Yeruşalem'de kendisine bunlar doğdu: Şimea, Şovav, Natan ve Solomon, dördü, Ammiel'in kızı Batşua'dan;"],["6","ve İvhar, Elişama, Elifelet,"],["7","Noga, Nefeg, Yafia,"],["8","Elişama, Eliyeda ve Elifelet, dokuz."],["9","Bunların hepsi David'in oğullarıydı, cariyelerin oğulları hariç; Tamar da onların kız kardeşiydi."],["10","Solomon'un oğlu Rehovam'dı; Aviya onun oğlu, Asa onun oğlu, Yehoşafat onun oğlu,"],["11","Yoram onun oğlu, Ahazya onun oğlu, Yoaş onun oğlu,"],["12","Amatsya onun oğlu, Azarya onun oğlu, Yotam onun oğlu,"],["13","Ahaz onun oğlu, Hizkiya onun oğlu, Manaşşe onun oğlu,"],["14","Amon onun oğlu Yoşiya onun oğlu."],["15","Yoşiya'nın oğulları: İlk oğlu Yohanan, ikincisi Yehoyakim, üçüncüsü Sidkiya ve dördüncüsü Şallum."],["16","Yehoyakim'in oğulları: Oğlu Yekonya ve oğlu Sidkiya."],["17","Sürgün olan Yekonya'nın oğulları: Onun oğlu Şealtiel,"],["18","Malkiram, Pedaya, Şenazar, Yekamya, Hoşama ve Nedavya."],["19","Pedaya'nın oğulları: Zerubbabel ve Şimei. Zerubbabel'in oğulları: Meşullam ve Hananya; onların kız kardeşi Şelomit'ti;"],["20","Haşuva, Ohel, Berekya, Hasadya ve Yuşav Hesed, beş."],["21","Hananya'nın oğulları: Pelatya ve Yeşaya; Refaya'nın oğulları, Arnan'ın oğulları, Ovadya'nın oğulları, Şekanya'nın oğulları."],["22","Şekanya'nın oğlu: Şemaya. Şemaya'nın oğulları: Hattuş, İgal, Barya, Nearya ve Şafat, altı."],["23","Neraya'nın oğulları: Elyoenay, Hizkiya ve Azrikam, üç."],["24","Elyoenay'ın oğulları: Hodavya, Elyaşiv, Pelaya, Akkub, Yohanan, Delaya ve Anani; yedi."]],4:[["1","Yahuda'nın oğulları: Perez, Hetsron, Karmi, Hur ve Şoval."],["2","Şoval'ın oğlu Reaya, Yahat'ın babası oldu; Yahat da Ahumay ve Lahad'ın babası oldu. Bunlar Soralılar'ın boylarıdır."],["3","Etam'ın babasının oğulları şunlardır: Yizreel, İşma ve İdvaş. Kız kardeşlerinin adı Hazzelelponi'ydi."],["4","Penuel, Gedor'un babasıydı ve Ezer, Huşa'nın babasıydı. Bunlar, Efrata'nın ilk oğlu Hur'un, Beytlehem'in babasıdır."],["5","Tekoa'nın babası Aşhur'un iki karısı vardı: Helah ve Naara."],["6","Naara ona Ahuzzam, Hefer, Temeni ve Haahaştari'yi doğurdu. Bunlar Naara'nın oğullarıydı."],["7","Helah'ın oğulları Seret, Yitshar ve Etnan'dı."],["8","Hakkots, Anuv'un, Soveva'nın ve Harum'un oğlu Aharhel boylarının atası oldu."],["9","Yaves kardeşlerinden daha saygındı. Annesi ona Yaves adını verdi, “Çünkü onu acı çekerek doğurdum” dedi."],["10","Yaves, İsrael'in Tanrısı'na feryat edip, “Keşke beni gerçekten kutsasan ve sınırımı genişletsen! Elin benimle olsun ve acı çekmeyeyim diye beni kötülükten koru!” dedi. Tanrı ona istediğini verdi."],["11","Şuha'nın kardeşi Keluv, Eşton'un babası olan Mehir'in babası oldu."],["12","Eşton, Beyt Rafa, Paseah ve İr Nahaş'ın babası Tehinna'nın babası oldu. Bunlar Reka adamlarıdır."],["13","Kenaz'ın oğulları: Otniel ve Seraya. Otniel’in oğulları: Hatat."],["14","Meonotay, Ofra’nın babası oldu; Seraya, Ge Haraşim’in babası Yoav’ın babası oldu; çünkü onlar zanaatkârlardı."],["15","Yefunne’nin oğlu Kalev’in oğulları: İru, Ela ve Naam. Ela’nın oğlu: Kenaz."],["16","Yehallelel’in oğulları: Zif, Zifa, Tirya ve Asarel."],["17","Ezra’nın oğulları: Yeter, Mered, Efer ve Yalon. Mered’in karısı Miryam’ı, Şammay’ı ve Eştemoa’nın babası İşva’yı doğurdu."],["18","Yahudi olan karısı, Gedor’un babası Yered’i, Soko’nun babası Hever’i ve Sanoah’ın babası Yekutiel’i doğurdu. Bunlar, Mered’in aldığı Firavun’un kızı Bitya’nın oğullarıydı."],["19","Naham'ın kız kardeşi Hodiya'nın karısının oğulları, Keilalı Garmlılar'ın ve Eştemoalı Maakalılar'ın atalarıydı."],["20","Şimon'un oğulları: Amnon, Rinna, Ben Hanan ve Tilon. Yişi'nin oğulları: Zohet ve Ben Zohet."],["21","Yahuda oğlu Şela'nın oğulları: Leka'nın babası Er, Mareşah'ın babası Laada ve ince keten yapanlar evinin, Aşvea evinin boyları;"],["22","Yokim ve Moav ve Yaşubilehem'de hakimiyet kuran Kozeva adamları, Yoaş ve Saraf. Bu kayıtlar eskidir."],["23","Bunlar çömlekçiler ve Netaim ve Gederah sakinleriydi; kralın işinde onunla birlikte orada yaşıyorlardı."],["24","Şimon'un oğulları: Nemuel, Yamin, Yariv, Zerah, Şaul;"],["25","Onun oğlu Şallum, onun oğlu Mivsam, onun oğlu Mişma."],["26","Mişma'nın oğulları: Onun oğlu Hammuel, onun oğlu Zakkur, onun oğlu Şimei."],["27","Şimei'nin on altı oğlu ve altı kızı vardı; ama kardeşlerinin çok çocuğu yoktu ve bütün boyları Yahuda'nın çocukları gibi çoğalmadı."],["28","Beerşeva'da, Molada'da, Hazarşual'da,"],["29","Bilha'da, Esem'de, Tolad'da,"],["30","Betuel'de, Horma'da, Ziklag'da,"],["31","Bet Markavot'ta, Hazar Susim'de, Beyt Biri'de ve Şaaraim'de oturdular. David'in krallığına kadar kentleri bunlardı."],["32","Köyleri Etam, Ayn, Rimmon, Token ve Aşan'dı; beş kent;"],["33","Ve aynı kentlerin çevresindeki Baal'a kadar bütün köyler onlarındı. Yerleşim yerleri bunlardı ve soy kütüklerini tuttular."],["34","Meşovav, Yamlek, Amatsya'nın oğlu Yoşa,"],["35","Yoel, Asiel oğlu Seraya oğlu Yoşivya oğlu Yehu,"],["36","Elioenay, Yaakovah, Yeşohayya, Asaya, Adiel, Yesimiel, Benaya,"],["37","Ve Şemaya oğlu, Şimri'nin oğlu, Yedaya'nın oğlu, Allon'un oğlu, Şifi'nin oğlu Ziza."],["38","Bunların adları anılanlar, kendi ailelerinde beylerdi. Atalarının evleri çok çoğaldı."],["39","Sürüleri için otlak aramak üzere Gedor girişine, vadinin doğu tarafına gittiler."],["40","Bol ve iyi otlaklar buldular. Ülke geniş, sakin ve huzurluydu. Çünkü daha önce orada yaşayanlar Ham soyundandı."],["41","Bunlar, Yahuda Kralı Hizkiya'nın günlerinde adları yazılı olanlar geldiler ve onların çadırlarını ve orada bulunan Meunlar'ı vurdular; ve onları tamamen yok ettiler, bügüne dek böyledir ve onların yerinde yaşadılar, çünkü orada sürüleri için otlak vardı."],["42","Onlardan bazıları, Şimonoğulları'ndan beş yüz kişi, Seir dağına gittiler; ve onların başları Yişi'nin oğulları Pelatya, Nearya, Refaya ve Uzziel'di."],["43","Amalekliler'in kaçaklarından geri kalanını vurdular ve bugüne dek orada yaşadılar."]],5:[["1","İsrael'in ilk oğlu Ruven'in oğulları (Çünkü ilk doğan oydu, ama babasının yatağını kirlettiği için ilk oğulluk hakkı İsrael'in oğlu Yosef'in oğullarına verildi; ve soy kütüğü ilk oğulluk hakkına göre sayılmadı."],["2","Çünkü Yahuda kardeşlerinden üstün geldi ve hükümdar ondan çıktı; ama ilk oğulluk hakkı Yosef''indi)"],["3","İsrael'in ilk oğlu Ruven'in oğulları: Hanok, Pallu, Hetsron ve Karmi."],["4","Yoel'in oğulları: Onun oğlu Şemaya, onun oğlu Gog, onun oğlu Şimei,"],["5","Onun oğlu Mika, onun oğlu Reaya, onun oğlu Baal,"],["6","ve onun oğlu Beera, Aşur Kralı Tilgat Pilneser'in sürgüne gönderdiği kişiydi. Ruvenliler'in beyiydi."],["7","Boylarına göre kardeşleri, kuşaklarının soyağacına göre sayıldığında: Baş Yeiel ve Zekariya,"],["8","Ve Yoel oğlu Şema oğlu Azaz oğlu Bela, o Nebo'ya ve Baal Meon'a kadar Aroer'de yaşıyordu;"],["9","ve Gilad ülkesinde hayvanları çoğaldığı için, Fırat Irmağı'ndan çölün girişine kadar doğuda yaşadı."],["10","Saul'un günlerinde, onların eliyle düşen Hagriler ile savaştılar; ve Gilad'ın doğusundaki bütün ülkede çadırlarında yaşadılar."],["11","Gadoğulları Başan ülkesinde Saleka'ya kadar onların yanında yaşadılar:"],["12","Başı Yoel, ikincisi Şafam, Yanay ve Başan'da Şafat."],["13","Ataları evlerinden olan kardeşleri: Mikael, Meşullam, Şeva, Yoray, Yakan, Zia ve Ever, yedi."],["14","Bunlar Huri oğlu, Yaroah oğlu, Gilad oğlu, Mikael oğlu, Yeşişay oğlu, Yahdo oğlu, Buz oğlu Avihayil'in oğullarıydı."],["15","Guni oğlu Avdiel oğlu Ahi ataları evlerinin başıydı."],["16","Gilad'da, Başan'da ve kasabalarında, Şaron'un bütün otlaklarında da, onların sınırlarına kadar yaşıyorlardı."],["17","Bunların hepsi Yahuda Kralı Yotam'ın ve İsrael Kralı Yarovam'ın günlerinde soy kütüklerine göre sayıldı."],["18","Ruvenoğulları, Gadlılar ve Manaşşe'nin yarım oymağı, yiğit adamlardan, kalkan ve kılıç taşıyabilen, yay ile ok atabilen ve becerikli savaşa çıkabilen kırk dört bin yedi yüz altmış kişiydi."],["19","Hagrilerle, Yetur, Nafiş ve Nodav'la savaştılar."],["20","Onlara karşı yardım gördüler ve Hagriler ve onlarla birlikte olanların hepsi onların eline teslim edildi; çünkü savaşta Tanrı'ya feryat ettiler ve O da onlara yanıt verdi, çünkü O'na güvenmişlerdi."],["21","Onların hayvanlarını alıp götürdüler: Develerinden elli bin, koyunlarından iki yüz elli bin, eşeklerinden iki bin, adamlarından da yüz bin."],["22","Çünkü savaş Tanrı'dan olduğu için düşüp ölen çok oldu. Sürgüne dek onların yerinde yaşadılar."],["23","Manaşşe'nin yarım oymağı çocukları ülkede yaşadılar. Başan'dan Baal Hermon, Senir ve Hermon Dağı'na kadar çoğaldılar."],["24","Ataları evlerinin başları şunlardı: Efer, Yişi, Eliel, Azriel, Yeremya, Hodavya ve Yahdiel. Bunlar cesur yiğitler, ünlü adamlardı, ataları evlerinin başlarıydı."],["25","Atalarının Tanrısı'na karşı suç işlediler ve Tanrı'nın önlerinden yok ettiği ülke halklarının ilâhları ardınca fahişelik ettiler."],["26","Böylece İsrael'in Tanrısı, Aşur Kralı Pul'un ve Aşur Kralı Tilgat Pilneser'in ruhunu harekete geçirdi ve Ruvenliler'i, Gadlılar'ı ve Manaşşe'nin yarım oymağını sürüp Halah'a, Habor'a, Hara'ya ve Gozan Irmağı'na götürdü; bugüne dek öyledir."]],6:[["1","Levi'nin oğulları: Gerşon, Kehat ve Merari."],["2","Kohat'ın oğulları: Amram, Yitshar, Hevron ve Uzziel."],["3","Amram'ın oğulları: Aron, Moşe ve Miryam. Aron'un oğulları: Nadav, Avihu, Eleazar ve İtamar."],["4","Eleazar, Pinehas'ın babası oldu. Pinehas, Abişua'nın babası oldu."],["5","Avişua, Bukki'nin babası oldu. Bukki, Uzzi'nin babası oldu."],["6","Uzzi, Zerahya'nın babası oldu. Zerahya, Merayot'un babası oldu."],["7","Merayot, Amarya'nın babası oldu. Amarya, Ahituv'un babası oldu."],["8","Ahituv, Sadok'un babası oldu. Sadok, Ahimaats'ın babası oldu."],["9","Ahimaats, Azarya'nın babası oldu. Azarya, Yohanan'ın babası oldu."],["10","Yohanan, Solomon'un Yeruşalem'de yaptırdığı evde kâhinlik görevini yürüten Azarya'nın babası oldu."],["11","Azarya, Amarya'nın babası oldu. Amarya, Ahituv'un babası oldu."],["12","Ahituv, Sadok'un babası oldu. Sadok, Şallum'un babası oldu."],["13","Şallum, Hilkiya'nın babası oldu. Hilkiya, Azarya'nın babası oldu."],["14","Azarya, Seraya'nın babası oldu. Seraya, Yehotsadak'ın babası oldu."],["15","Yahve Nebukadnetsar'ın eliyle Yahuda ve Yeruşalem'i sürdüğü zaman, Yehotsadak sürgüne gitti."],["16","Levi'nin oğulları: Gerşom, Kehat ve Merari."],["17","Gerşom'un oğullarının adları şunlardır: Livni ve Şimei."],["18","Kohat'ın oğulları: Amram, Yitshar, Hevron ve Uzziel'di."],["19","Merari'nin oğulları: Mahli ve Muşi. Bunlar, ataları evlerine göre Levililer'in boylarıdır."],["20","Gerşom'dan: Onun oğlu Livni, onun oğlu Yahat, onun oğlu Zimmah,"],["21","onun oğlu Yoah, onun oğlu İddo, onun oğlu Zerah ve onun oğlu Yeateray."],["22","Kohat'ın oğulları: Onun oğlu Amminadav, onun oğlu Korah, onun oğlu Assir,"],["23","onun oğlu Elkana, onun oğlu Eviasaf, onun oğlu Assir,"],["24","onun oğlu Tahat, onun oğlu Uriel, onun oğlu Uzziya ve onun oğlu Şaul."],["25","Elkana'nın oğulları: Amasay ve Ahimot."],["26","Elkana'ya gelince, Elkana'nın oğulları: Onun oğlu Sofay, onun oğlu Nahat,"],["27","onun oğlu Eliav, onun oğlu Yeroham ve onun oğlu Elkana."],["28","Samuel'in oğulları: İlk oğlu Yoel, ikincisi Aviya."],["29","Merari'nin oğulları: Mahli, oğlu Livni, oğlu Şimei, oğlu Uzza,"],["30","onun oğlu Şimea, onun oğlu Haggya, onun oğlu Asaya."],["31","Bunlar, David'in, Sandık oraya dinlenmeye geldikten sonra, Yahve'nin evinde ilahi söyleme hizmetine koyduğu kişilerdir."],["32","Solomon, Yeruşalem'de Yahve'nin evini bina edene kadar, Buluşma Çadırı meskeni önünde ilahi söyleyerek hizmet ettiler. Görevlerini sıralarına göre yerine getirdiler."],["33","Hizmet edenler ve oğulları şunlardır: Kohatoğulları'ndan: Samuel oğlu Yoel oğlu ilahi söyleyen Heman,"],["34","Toah oğlu, Eliel oğlu, Yeroham oğlu, Elkana oğlu,"],["35","Amasay oğlu Mahat oğlu Elkana oğlu Suf oğlu,"],["36","Sefanya oğlu Azarya oğlu Yoel oğlu Elkana oğlu,"],["37","Korah oğlu, Evyasaf oğlu, Assir oğlu, Tahat oğlu,"],["38","İsrael oğlu, Levi oğlu, Kohat oğlu, Yitshar oğlu."],["39","Sağında duran onun kardeşi Asaf, Şimea oğlu, Berekya oğlu Asaf,"],["40","Malkiya oğlu, Baaseya oğlu Mikael oğlu,"],["41","Adaya oğlu, Serah oğlu Etni oğlu,"],["42","Şimei oğlu, Zimma oğlu, Etan oğlu,"],["43","Levi oğlu, Gerşom oğlu, Yahat"],["44","Sol tarafta onların kardeşleri Merarioğulları: Malluk oğlu, Avdi oğlu, Kişi oğlu Etan,"],["45","Hilkiya oğlu, Amatsya oğlu, Haşavya oğlu,"],["46","Şemer oğlu, Bani oğlu, Amtsi oğlu,"],["47","Levi oğlu, Merari oğlu, Muşi oğlu, Mahli oğlu."],["48","Tanrı Evi'nin çadırının bütün hizmeti için kardeşleri Levililer atandı."],["49","Ama Aron ve oğulları, Tanrı'nın hizmetkârı Moşe'nin buyurduğu her şeye göre, yakmalık sunu sunağında ve buhur sunağında, En Kutsal Yer'in bütün işleri için ve İsrael için kefaret etmek üzere sunular sundular."],["50","Aron'un oğulları şunlardır: Onun oğlu Eleazar, onun oğlu Pinehas, onun oğlu Avişua,"],["51","onun oğlu Bukki, onun oğlu Uzzi, onun oğlu Zerahya,"],["52","onun oğlu Merayot, onun oğlu Amarya, onun oğlu Ahituv,"],["53","onun oğlu Sadok ve onun oğlu Ahimaats."],["54","Şimdi, sınırlarında ordugâhlarına göre meskenleri şunlardır: Kohatlılar'ın boylarından Aronoğulları'na (çünkü ilk kura onlarındı),"],["55","Yahuda ülkesindeki Hevron'u ve çevresindeki otlakları onlara verdiler."],["56","Ancak kentin tarlalarını ve köylerini Yefunne oğlu Kalev'e verdiler."],["57","Aronoğulları'na sığınma kentlerini verdiler: Hevron, otlaklarıyla Livna, Yattir, Eştemoa, otlaklarıyla,"],["58","Hilen otlaklarıyla, Devir otlaklarıyla,"],["59","Aşan otlaklarıyla ve Beyt Şemeş otlaklarıyla;"],["60","ve Benyamin oymağından, Giva otlaklarıyla, Allemet otlaklarıyla ve Anatot otlaklarıyla. Boylarına göre bütün kentleri on üç kentti."],["61","Kohatoğulları'nın geri kalanına, bu oymağın boylarından, yarım oymak, Manaşşe'nin yarısından, on kent kurayla verildi."],["62","Gerşomoğulları'na, boylarına göre, İssakar oymağından, Aşer oymağından, Naftali oymağından ve Başan'daki Manaşşe oymağından, on üç kent verildi."],["63","Merarioğulları'na, boylarına göre, Ruven oymağından, Gad oymağından ve Zevulun oymağından on iki kent kurayla verildi."],["64","İsrael'in çocukları, Levililer'e otlaklarıyla birlikte o kentleri verdiler."],["65","Yahuda'nın çocukları oymağından, Şimon'un çocukları oymağından, Benyamin'in çocukları oymağından adlarıyla anılan şu kentleri kura ile verdiler."],["66","Kohatoğulları'nın bazı oymaklarının Efraim oymağından sınır kentleri vardı."],["67","Onlara sığınma kentleri verildi: Efraim dağlık bölgesindeki Şekem ile otlaklarını ve Gezer ile otlaklarını,"],["68","Yokmeam ile otlaklarını ve Beyt Horon ile otlaklarını,"],["69","Ayalon ile otlaklarını ve Gat Rimmon ile otlaklarını;"],["70","Manaşşe'nin yarım oymağından da Aner ile otlaklarını, Bileam ile otlaklarını, Kohatoğulları boyunun geri kalanına verdiler."],["71","Manaşşe yarım oymağının Gerşomoğulları'na, Başan'daki Golan ile otlaklarını, Aştarot ile otlaklarını;"],["72","İssakar oymağından Kedeş ile otlaklarını, Daverat ile otlaklarını,"],["73","Ramot ile otlaklarını, Anem ile otlaklarını;"],["74","Aşer oymağından Maşal ile otlaklarını, Avdon ile otlaklarını,"],["75","Hukok ile otlaklarını, Rehov ile otlaklarını;"],["76","Naftali oymağından Galile'deki Kedeş ile otlaklarını, Hammon ile otlaklarını, Kiriatayim ile otlaklarını verdiler."],["77","Merarioğulları'na, Levililer'in geri kalanına, Zevulun oymağından, Rimmon ile otlaklarını ve Tabor ile otlaklarını,"],["78","Yarden'in ötesinde, Yeriha'da, Yarden'in doğusunda, Ruven oymağından, çölde Betser ile otlaklarını, Yahtsa ile otlaklarını,"],["79","Kedemot ile otlaklarını Mefaat ile otlaklarını,"],["80","Gad oymağından, Gilad'da Ramot ile otlaklarını, Mahanaim ile otlaklarını,"],["81","Heşbon ile otlaklarını, Yatser ile otlaklarını verdiler."]],7:[["1","İssakaroğulları'ndan: Tola, Pua, Yaşuv ve Şimron, dört."],["2","Tolaoğulları: Uzzi, Refaya, Yeriel, Yahmay, İvsam ve Şemuel, ataları evlerinin başları, Tola'dan; kuşaklarından cesur yiğitler. David'in günlerinde onların sayıları yirmi iki bin altı yüzdü."],["3","Uzzi'nin oğlu: İzrahya. İzrahya'nın oğulları: Mikael, Ovadya, Yoel ve İşşiya, beş; hepsi de baş adamlardı."],["4","Onlarla birlikte, kuşaklarına göre, ataları evlerine göre, savaş için ordu birlikleri, otuz altı bin; çünkü çok karıları ve oğulları vardı."],["5","İssakar'ın bütün boyları arasında, soy kütüğüne göre sayılan cesur yiğitler, kardeşleri seksen yedi bindi."],["6","Benyamin'in oğulları: Bela, Beker ve Yediael, üç."],["7","Bela'nın oğulları: Etsvon, Uzzi, Uzziel, Yerimot ve İri, beş; atalar evlerinin başları, cesur yiğitler; ve soy kütüğüne göre yirmi iki bin otuz dört kişi sayıldı."],["8","Beker'in oğulları: Zemirah, Yoaş, Eliezer, Elyoenay, Omri, Yeremot, Aviya, Anatot ve Alemet. Bunların hepsi Beker'in oğullarıydı."],["9","Kuşaklarına göre soy kütüğüne göre, ataları evlerinin başları, cesur yiğitler, yirmi bin iki yüz kişi sayıldı."],["10","Yediael'in oğlu: Bilhan. Bilhan'ın oğulları: Yeuş, Benyamin, Ehud, Kenaana, Zetan, Tarşiş ve Ahişahar."],["11","Bütün bunlar, ataları evlerinin başlarına göre, Yediael'in oğullarıydı; savaşa gidebilecek kadar güçlü, cesur yiğitlerdi. On yedi bin iki yüz."],["12","Şuppim, Huppim, İr'in oğulları, Aher'in oğulları, Huşim."],["13","Naftali'nin oğulları: Yahziel, Guni, Yeser, Şallum ve Bilha'nın oğulları."],["14","Manaşşe'nin oğulları: Aramlı cariyesi Asriel'i doğurdu. O, Gilad'ın babası Makir'i doğurdu."],["15","Makir, Huppim ve Şuppim'den bir karı aldı. Kız kardeşinin adı Maaka'ydı. İkincisinin adı Selofhad'dı. Selofhad'ın da kızları oldu."],["16","Makir'in karısı Maaka bir oğul doğurdu ve adını Pereş koydu. Kardeşinin adı Şereş'ti. Onun oğulları da Ulam ve Rakem'diler."],["17","Ulam'ın oğulları: Bedan. Bunlar Manaşşe'nin oğlu Makir'in oğlu Gilad'ın oğullarıydı."],["18","Kız kardeşi Hammoleket, İşhod'u, Aviezer'i ve Mahla'yı doğurdu."],["19","Şemida'nın oğulları: Ahian, Şekem, Likhi ve Aniam idi."],["20","Efraim'in oğulları: Şutelah, onun oğlu Bered, onun oğlu Tahat, onun oğlu Eleada, onun oğlu Tahat,"],["21","onun oğlu Zavad, onun oğlu Şutelah, Ezer ve Elead. Bunları ülkede doğmuş olan Gatlılar öldürdüler, çünkü onların hayvanlarını alıp götürmek için inmişlerdi."],["22","Babaları Efraim günlerce yas tuttu ve kardeşleri onu avutmak için geldiler."],["23","Karısının yanına girdi, kadın gebe kaldı ve bir oğul doğurdu ve babası evinde sıkıntı olduğu için adını Beria koydu."],["24","Kızı, Aşağı ve Yukarı Beyt Horon'u ve Uzzen Şerah'ı kuran Şeera'ydı."],["25","Refah onun oğluydu ve Reşef, onun oğlu Telah, onun oğlu Tahan,"],["26","Onun oğlu Ladan, onun oğlu Ammihud, onun oğlu Elişama,"],["27","onun oğlu Nun ve onun oğlu Yeşu'ydu."],["28","Mülkleri ve yerleşim yerleri Beytel ve kasabaları, doğuda Naaran, batıda Gezer ve kasabaları, Şekem ve kasabaları, Azza ve kasabalarına kadar;"],["29","Manaşşeoğulları'nın sınırları yanında ise Beyt Şean ve kasabaları, Taanak ve kasabaları, Megiddo ve kasabaları, Dor ve kasabalarıydı. İsrael oğlu Yosef'in çocukları buralarda yaşıyordu."],["30","Aşer'in oğulları: İmna, Yişva, Yişvi ve Beria. Serah kız kardeşleriydi."],["31","Beria’nın oğulları: Hever ve Birzait'in babası olan Malkiel."],["32","Hever, Yaflet’in, Şomer’in, Hotam’ın ve onların kız kardeşleri Şua’nın babası oldu."],["33","Yaflet’in oğulları: Pasak, Bimhal ve Aşvat. Bunlar Yaflet’in oğullarıydı."],["34","Şemer’in oğulları: Ahi, Rohga, Yehubba ve Aram."],["35","Kardeşi Helem’in oğulları: Sofah, İmna, Şeleş ve Amal."],["36","Sofah’ın oğulları: Suah, Harnefer, Şual, Beri, İmra,"],["37","Bezer, Hod, Şamma, Şilshah, İtran ve Beera."],["38","Yeter’in oğulları: Yefunne, Pispa ve Ara."],["39","Ulla’nın oğulları: Arah, Hanniel ve Ritsya."],["40","Bunların hepsi Aşer'in çocuklarıydı, ata evlerinin başlarıydı, cesur seçkin yiğitlerdi, beylerin başlarıydılar. Savaşta hizmet için soy kütüğüne göre sayılanların sayısı yirmi altı bin kişiydi."]],8:[["1","Benyamin, ilk oğlu Bela'nın, ikinci oğlu Aşvel'in, üçüncü oğlu Aharah'ın,"],["2","dördüncü oğlu Noha'nın ve beşinci oğlu Rafa'nın babası oldu."],["3","Bela'nın oğulları vardı: Addar, Gera, Avihud,"],["4","Avişua, Naaman, Ahoah,"],["5","Gera, Şefufan ve Huram."],["6","Bunlar Ehud'un oğullarıydı. Bunlar, Manahat'a sürgün edilen Geva sakinlerinin ataları evlerinin başlarıydı:"],["7","Naaman, Ahiya ve Gera, onları sürgün eden buydu ve Uzza ile Ahihud'un babası oldu."],["8","Şaharayim, onları gönderdikten sonra Moav kırlarında çocuklar babası oldu. Karıları Huşim ve Baara'ydı."],["9","Karısı Hodeş'ten Yovav'ın, Sîvya'nın, Meşa'nın, Malkam'ın,"],["10","Yeuts'un, Şakya'nın ve Mirma'nın babası oldu. Bunlar onun oğullarıydı, atalar evlerinin başlarıydı."],["11","Huşim'den Avituv ve Elpaal'ın babası oldu."],["12","Elpaal'ın oğulları: Ever, Mişam, Ono ve Lod ile kasabalarını kuran Şemed;"],["13","Ayalon sakinlerinin ataları evlerinin başları olan ve Gat sakinlerini kaçıran Beria ve Şema;"],["14","Ahio, Şaşak, Yeremot,"],["15","Zevadya, Arad, Eder,"],["16","Mikael, İşpa, Yoha, Beria'nın oğulları,"],["17","Zevadya, Meşullam, Hizki, Hever,"],["18","İşmeray, İzliya, Yovav, Elpaal'ın oğulları,"],["19","Yakim, Zikri, Zavdi,"],["20","Elienay, Silletay, Eliel,"],["21","Adaya, Beraya, Şimrat, Şimei'nin oğulları,"],["22","İşpan, Ever, Eliel,"],["23","Avdon, Zikri, Hanan,"],["24","Hananya, Elam, Antotiya,"],["25","İfdeya, Penuel, Şaşak'ın oğulları,"],["26","Şamşeray, Şehariya, Atalya,"],["27","Yaareşiya, Eliya, Zikri ve Yeroham."],["28","Bunlar kuşaklar boyunca atalar evlerinin başları, önderlerdi. Bunlar Yeruşalem'de yaşadılar."],["29","Karısının adı Maaka olan Givon'un babası, Givon'da yaşadı."],["30","İlk oğlu Avdon ile, Sur, Kiş, Baal, Nadav,"],["31","Gedor, Ahio, Zeker,"],["32","ve Şimeah'ın babası olan Miklot da orada yaşadı. Bunlar da aileleriyle birlikte Yeruşalem'de, akrabalarının yanında yaşadılar."],["33","Ner, Kiş'in babası oldu. Kiş, Saul'un babası oldu. Saul, Yonatan'ın, Malkişua'nın, Avinadav'ın ve Eşvaal'ın babası oldu."],["34","Yonatan'ın oğlu Meriv Baal'dı. Meriv Baal, Mika'nın babası oldu."],["35","Mika'nın oğulları: Piton, Melek, Tarea ve Ahaz."],["36","Ahaz, Yehoaddah'ın babası oldu. Yehoaddah, Alemet'in, Azmavet'in ve Zimri'nin babası oldu. Zimri, Motsa'nın babası oldu."],["37","Motsa, Binea'nın babası oldu. Rafa onun oğluydu, Eleasa onun oğluydu ve Atsel de onun oğluydu."],["38","Atsel'in altı oğlu vardı. Adları şunlardır: Atsrikam, Bokeru, İşmael, Şearya, Ovadya ve Hanan. Bunların hepsi Atsel'in oğullarıydı."],["39","Kardeşi Esek'in oğulları: İlk oğlu Ulam, ikincisi Yeuş ve üçüncüsü Elifelet."],["40","Ulam'ın oğulları cesur, okçu yiğitlerdi ve oğulları ve torunları çoktu, yüz elli. Bunların hepsi Benyamin'in oğullarındandı."]],9:[["1","Böylece bütün İsrael soy kütüklerine göre sayıldılar; ve işte, bunlar İsrael krallarının kitabında yazılıdır. Yahuda, itaatsizliği yüzünden Babil'e sürgün edildi."],["2","Kentlerindeki mülklerinde oturan ilk sakinler İsrael, kâhinler, Levililer ve tapınak görevlileriydi."],["3","Yeruşalem'de Yahuda'nın çocuklarından, Benyamin'in çocuklarından, Efraim'in ve Manaşşe'nin çocuklarından şunlar oturuyordu:"],["4","Yahudanın oğlu Peretsin çocuklarından: Bani'nin oğlu, İmri'nin oğlu, Omri'nin oğlu, Ammihud'un oğlu Utay."],["5","Şilolular'dan: İlk oğlu Asaya ve oğulları."],["6","Zeraoğulları'ndan: Yeuel ve kardeşleri, altı yüz doksan."],["7","Benyaminoğulları'ndan: Hassenua oğlu Hodavya oğlu Meşullam oğlu Sallu;"],["8","ve Yeroham'ın oğlu İvneya, ve Mikrinin oğlu, Uzzi oğlu Ela, ve İbniya'nın oğlu, Reuelin oğlu, Şefatya oğlu Meşullam;"],["9","ve onların kardeşleri, soylarına göre, dokuz yüz elli altı. Bunların hepsi ataları evlerine göre atalar evlerinin başlarıydı."],["10","Kâhinlerden: Yedaya, Yehoyariv, Yakin,"],["11","Tanrı evinin yöneticisi Ahitiuv'un oğlu, Merayot'un oğlu, Sadok'un oğlu, Meşullam'ın oğlu, Hilkiya'nın oğlu Azarya;"],["12","ve Malkiya'nın oğlu, Paşhur'un oğlu, Yeroham'ın oğlu Adaya, ve İmmer'in oğlu, Meşillemit'in oğlu, Meşullam'ın oğlu, Yahzera'nın oğlu, Adiel'in oğlu Maasay;"],["13","ve atalar evlerinin başları olan kardeşleri, bin yedi yüz altmış; Tanrı evinin hizmetinde çok yetenekli adamlardı."],["14","Levililer'den: Merarioğulları'ndan Haşavya oğlu, Azrikam oğlu, Haşşuv oğlu Şemaya;"],["15","Bakbakkar, Hereş, Galal ve Asaf oğlu Zikri oğlu Mika oğlu Mattanya;"],["16","Yedutun oğlu, Galal oğlu Şemaya oğlu, Ovadya; ve Netofalılar'ın köylerinde yaşayan Elkana oğlu, Asa oğlu Berekya."],["17","Kapı bekçileri: Şallum, Akkuv, Talmon, Ahiman ve kardeşleri (Şallum baştı)."],["18","Daha önce doğu tarafındaki kral kapısında görev yapmışlardı. Levi'nin çocuklarının ordugâh kapı bekçileriydi bunlar."],["19","Şallum, Kore'nin oğlu, Evyasaf'ın oğlu, Korah'ın oğluydu. Atalar evinden olan kardeşleri, Korahlılar, hizmet işi üzerinde, çadır eşiklerinin bekçileriydiler. Ataları, Yahve'nin ordugâhı üzerinde, girilecek yerin bekçileri olmuşlardı."],["20","Eleazar'ın oğlu Pinehas eskiden onların başındaydı ve Yahve onunla birlikteydi."],["21","Meşelemya'nın oğlu Zekariya, Buluşma Çadırı'nın kapısının kapı bekçisiydi."],["22","Eşiklerde kapı bekçisi olarak seçilenlerin hepsi iki yüz on iki kişiydi. Bunlar, köylerinde soy kütüğüne göre yazılmıştı. David ve Gören Samuel, onları görevlerine atamışlardı."],["23","Böylece kendileri ve çocukları, Yahve'nin evinin kapılarını, çadır evini muhafız olarak bakıyorlardı."],["24","Dört tarafta, doğuya, batıya, kuzeye ve güneye doğru kapıcılar vardı."],["25","Köylerindeki kardeşleri, zaman zaman onlarla birlikte olmak için her yedi günde bir gelirlerdi."],["26","Çünkü Levili olan dört baş kapı bekçisi, görevdeydiler ve Tanrı evindeki odaların ve hazinelerin başındaydı."],["27","Tanrı evinin çevresinde kalırlardı, çünkü bu onların göreviydi ve onu her sabah açmak onların göreviydi."],["28","Bazıları hizmet kaplarından sorumluydu, çünkü bunlar sayıyla içeri getirilirdi ve bunlar sayıyla dışarı çıkarılırdı."],["29","Onlardan bazıları da eşyaların ve kutsal yerin bütün kaplarının, ince unun, şarabın, yağın, günlük ve baharatların başına atandı."],["30","Kâhin oğullarından bazıları baharatların karıştırılmasını hazırlardı."],["31","Korahlı Şallum'un ilk oğlu olan Levililer'den Mattitya, tava işleri üzerinde görevliydi."],["32","Kohatoğulları'ndan olan kardeşlerinden bazıları, her Şabat Günü sergi ekmeği hazırlamak için görevliydi."],["33","Bunlar, Levililer'in ata evlerinin başları olan ezgi söyleyenlerdi. Odalarda yaşarlardı ve başka bir hizmetten muaf olurlardı. Çünkü gece gündüz işleriyle meşguldüler."],["34","Bunlar, kuşaklar boyunca Levililer'in ata evlerinin başları, önderlerdi. Yeruşalem'de yaşarlardı."],["35","Karısının adı Maaka olan Givon'un babası Yeiel, Givon'da yaşardı."],["36","İlk oğlu Avdon'du; sonra Sur, Kiş, Baal, Ner, Nadav,"],["37","Gedor, Ahio, Zekariya ve Miklot."],["38","Miklot, Şimeam'ın babası oldu. Onlar da akrabalarının yanında, Yeruşalem'de onlara yakın yaşıyorlardı."],["39","Ner, Kiş'in babası oldu. Kiş, Saul'un babası oldu. Saul, Yonatan, Malkişua, Avinadav ve Eşbaal'ın babası oldu."],["40","Yonatan'ın oğlu Merib Baal'dı. Merib Baal, Mika'nın babası oldu."],["41","Mika'nın oğulları: Piton, Melek, Tahrea ve Ahaz."],["42","Ahaz, Yarah'ın babası oldu. Yarah, Alemet, Azmavet ve Zimri'nin babası oldu. Zimri, Motsa'nın babası oldu."],["43","Motsa, Binea'nın babası oldu. Onun oğlu Refaya, onun oğlu Eleasah ve onun oğlu Atsel."],["44","Atsel'in altı oğlu vardı. Bunların adları Atsrikam, Bokeru, İşmael, Şearya, Ovadya ve Hanan'dı. Bunlar Atsel'in oğullarıydı."]],10:[["1","Filistliler İsrael'e karşı savaştılar. İsraelliler Filistliler'in önünden kaçtılar ve Gilboa Dağı'nda düşüp öldüler."],["2","Filistliler Saul'un ve oğullarının ardından sertçe geldiler. Filistliler Saul'un oğulları Yonatan'ı, Avinadav'ı ve Malkişua'yı öldürdüler."],["3","Saul'a karşı savaş sertleşti. Okçular onu bastırdı. Okçular yüzünden sıkıntıya girdi."],["4","Saul silahını taşıyan adama, “Kılıcını çek de onu bana sapla, yoksa sünnetsizler gelip beni taciz edebilirler” dedi. Ama silahını taşıyan adamı yapmak istemedi, çünkü çok korkmuştu. Bunun üzerine Saul kılıcını alıp onun üzerine düştü."],["5","Silahını taşıyan adam Saul'un öldüğünü görünce, kendisi de kılıcının üzerine düşüp öldü."],["6","Böylece Saul üç oğluyla birlikte öldü, bütün evi de birlikte öldü."],["7","Vadide bulunan bütün İsraelliler, onların kaçtıklarını ve Saul'un ve oğullarının öldüklerini görünce, kentlerini terk edip kaçtılar; Filistliler de gelip içlerinde yaşamaya başladılar."],["8","Ertesi gün, Filistliler öldürülenleri soymaya geldiklerinde, Saul'u ve oğullarını Gilboa Dağı'nda düşmüş buldular."],["9","Onu soyup başını ve zırhını aldılar, sonra Filist diyarının her yanına gönderip putlarına ve halka haber verdiler."],["10","Zırhını kendi ilâhlarının evine koydular ve başını Dagon'un evinin içinde çaktılar."],["11","Bütün Yaveş Gilad, Filistliler'in Saul'a yaptıklarını duyunca,"],["12","bütün yiğitler kalkıp Saul'un ve oğullarının cesetlerini aldılar ve Yaveş'e getirdiler, kemiklerini Yaveş'teki meşe ağacının altına gömdüler ve yedi gün oruç tuttular."],["13","Böylece Saul, Yahve'ye karşı işlediği suçtan, Yahve'nin sözünü tutmadığı için ve Yahve'ye sormayıp ruh çağıranlardan öğüt almak için sorduğu için,"],["14","Yahve onu öldürdü ve krallığı Yişay oğlu David'e devretti."]],11:[["1","Sonra bütün İsrael Hevron'da David'in yanına toplanıp dediler: “İşte, biz senin kemiğin ve senin etiniz."],["2","Geçmişte, Saul kralken, İsrael'i dışarı çıkaran ve içeri sokan sendin. Tanrın Yahve sana, 'Halkım İsrael'in çobanı sen olacaksın ve halkım İsrael'in üzerine sen hükümdar olacaksın' dedi.”"],["3","Böylece İsrael'in bütün ihtiyarları Hevron'daki kralın yanına geldiler; David de Hevron'da Yahve'nin önünde onlarla bir antlaşma yaptı. Yahve'nin Samuel aracılığıyla olan sözüne göre David'i İsrael üzerine kral olarak meshettiler."],["4","David ve bütün İsrael Yeruşalem'e (Yevus olarak da bilinir) gittiler; ve ülkenin sakinleri olan Yevuslular oradaydılar."],["5","Yevuslular David'e, “Buraya girmeyeceksin!” dediler. Buna rağmen David Siyon Kalesi'ni aldı. Orası David'in kentidir."],["6","David, “Yevuslular'ı önce vuran, baş ve komutan olacak” demişti. Seruya oğlu Yoav önce çıktı ve baş oldu."],["7","David kalede yaşıyordu; bu yüzden ona David kenti dediler."],["8","Kenti Millo'dan başlayarak çevresine kadar çepeçevre bina etti; Yoav da kentin geri kalanını onardı."],["9","David gittikçe büyüyordu; çünkü Ordular Yahvesi onunla birlikteydi."],["10","Yahve'nin İsrael için olan sözüne göre, David'i kral yapmak için kendisiyle ve bütün İsrael'le birlikte onun krallığında güç göstermiş olan David'in yiğitlerinin başları şunlardır;"],["11","David'in yiğitlerinin sayısı şudur: Otuzlar'ın başı Hakmonit oğlu Yaşoveam; mızrağını üç yüze karşı kaldırdı ve onları bir kerede öldürdü."],["12","Ondan sonra, üç yiğitten biri olan Ahohlu Dodo oğlu Eleazar."],["13","O David'le Pasdammim'deydi. Filistliler orada savaşmak için toplanmışlardı. Orada arpa dolu bir tarla vardı. Halk Filistliler'in önünden kaçtı."],["14","Onlar tarlanın ortasında durup onu savundular ve Filistliler'i öldürdüler. Yahve de onları büyük bir zaferle kurtardı."],["15","Baş Otuzlar'dan üçü kayaya, David'in yanına, Adullam Mağarası'na indiler. Filistliler'in ordusu Refaim Vadisi'nde ordugâh kurmuştu."],["16","David o sırada kaledeydi. Filistliler'in birliği de o sırada Beytlehem'deydi."],["17","David özlemle, “Keşke biri bana Beytlehem'deki kapının yanındaki kuyudan su verse!” dedi."],["18","Üçlü Filist ordusunu yarıp, Beytlehem'in kapısındaki kuyudan su çekip aldılar ve David'e getirdiler; ama David içmek istemedi, onu Yahve'ye döktü,"],["19","Ve şöyle dedi, “Tanrım, bunu yapmaktan beni alıkoysun! Canlarını tehlikeye koyan bu adamların kanını mı içeyim?” Çünkü onu getirmek için canlarını tehlikeye attılar. Bu yüzden içmek istemedi. Bu şeyleri üç yiğit yaptı."],["20","Üçler'in başı Yoav'ın kardeşi Avişay'dı; çünkü mızrağını üç yüze doğru kaldırıp onları öldürdü ve Üçler arasında üne sahipti."],["21","Üçler'in ikisinden daha saygındı ve onların başı oldu; ancak Üçler'e dahil değildi."],["22","Yehoyada oğlu Benaya, Kabseel'den cesur bir adamın oğluydu. O, kudretli işler yapmıştı. Moavlı Ariel'in iki oğlunu öldürdü. Karlı bir günde inip çukurun ortasında bir aslanı da öldürdü."],["23","İri yapılı, beş arşın boyunda bir Mısırlı'yı öldürdü. Mısırlı'nın elinde dokumacı sırığı gibi bir mızrak vardı. Bir değnekle ona doğru indi, mızrağı Mısırlı'nın elinden kaptı ve onu kendi mızrağıyla öldürdü."],["24","Yehoyada oğlu Benaya bu şeyleri yaptı ve üç yiğit arasında ünü vardı."],["25","İşte, Otuzlar'dan daha saygındı, ama Üçler'e erişemedi; David de onu muhafızlarının başına koydu."],["26","Orduların yiğitleri: Yoav'ın kardeşi Asahel, Beytlehemli Dodo oğlu Elhanan,"],["27","Harorlu Şammot, Pelonlu Heles,"],["28","Tekolu İkkeş oğlu İra, Anatotlu Aviezer,"],["29","Huşatlı Sivvekay, Ahohlu İlay,"],["30","Netofalı Maharay, Netofalı Baana oğlu Heled,"],["31","Benyamin'in çocuklarından Giva'lı Rivay oğlu İtay, Piratonlu Benaya,"],["32","Gaaş derelerinden Huray, Arbatlı Abiel,"],["33","Baharumlu Atsmavet, Şaalvonlu Eliahva,"],["34","Gizonlu Haşem'in oğulları, Hararlı Şagee oğlu Yonatan,"],["35","Hararlı Sakar oğlu Ahiam, Ur oğlu Elifal,"],["36","Mekeralı Hefer, Pelonlu Ahiya,"],["37","Karmelli Hetsro, Ezbay oğlu Naarai,"],["38","Natan'ın kardeşi Yoel, Hagri oğlu Mivhar,"],["39","Ammonlu Selek, Seruya oğlu Yoav'ın silah taşıyıcısı Berotlu Naharai,"],["40","İtritli İra, İtritli Garev,"],["41","Hititli Uriya, Ahlay oğlu Savad,"],["42","Ruvenliler'in başlarından Ruvenli Şitsa oğlu Adina ve onunla birlikte otuz kişi,"],["43","Maaka oğlu Hanan, Mitnitli Yoşafat,"],["44","Aşteralı Uzziya, Aroerli Hotam'ın oğulları Şama ve Yeiel,"],["45","Şimri oğlu Yediael, kardeşi Tizli Yoha,"],["46","Mahavlı Eliel, Elnaam'ın oğulları Yerivay ve Yoşavya, Moavlı İtma,"],["47","Eliel, Oved ve Metsobalı Yaasiel."]],12:[["1","Bunlar, Kiş oğlu Saul'dan kaçmakta olan David'in yanına, Ziklag'a gelenlerdi. Onlar savaşta ona yardımcı olan yiğitler arasındaydılar."],["2","Yaylarla silahlanmışlardı ve hem sağ ellerini hem de sol ellerini kullanarak taş atabiliyor ve yaydan ok atabiliyorlardı. Bunlar Benyamin oymağından Saul'un akrabalarıydı."],["3","Baş Ahiezer'di, sonra Givalı Şemaah'ın oğulları Yoaş; Azmavet'in oğulları Yeziel ve Pelet; Beraka; Anatotlu Yehu;"],["4","Otuzlar'dan bir yiğit olup ve Otuzlar'ın önderi olan Givonlu İşmaya; Yeremya; Yahaziel; Yohanan; Gederalı Yozavad;"],["5","Eluzay; Yerimot; Bealya; Şemarya; Haruplu Şefatya;"],["6","Korahlılar'dan Elkana, İşşiya, Azarel, Yoezer ve Yaşoveam;"],["7","Gedorlu Yeroham'ın oğulları Yoelah ve Zevadya."],["8","Çöldeki kalede David'e katılan bazı Gadlılar, savaşa hazır, kalkan ve mızrak kullanabilen cesur yiğitlerdi, yüzleri aslan yüzleri gibiydi ve dağlardaki ceylanlar kadar hızlıydılar:"],["9","Baş Ezer, ikincisi Ovadya, üçüncüsü Eliav,"],["10","Dördüncüsü Mişmanna, beşincisi Yeremya,"],["11","Altıncısı Attay, yedincisi Eliel,"],["12","Sekizinci Yohanan, dokuzuncusu Elzavad,"],["13","Onuncusu Yeremya ve on birincisi Makvannay'dı."],["14","Gadoğulları'ndan bunlar ordu komutanlarıydı. En küçüğü yüz adama, en büyüğü bin adama denkti."],["15","Bunlar, Yarden'in bütün kıyılarının taştığı birinci ayda ondan geçenlerdir; ve vadilerde oturanların hepsini hem doğuya hem de batıya doğru kaçırdılar."],["16","Benyamin'in ve Yahuda'nın çocuklarından bazıları David'in yanına, kaleye geldiler."],["17","David onları karşılamak için çıkıp onlara şöyle yanıt verdi: “Eğer bana yardım etmek için esenlikle bana geldiyseniz, yüreğim sizinle bir olacaktır; ama ellerimde hiçbir haksızık yokken, eğer beni düşmanlarımın eline vermek için geldiyseniz, atalarımızın Tanrısı bunu görsün ve onu azarlasın.”"],["18","O zaman Ruh Otuzlar'ın başı olan Amasay'ın üzerine geldi ve dedi: “Biz seniniz, ey David, senin tarafındayız, ey Yişay oğlu. Sana esenlik, esenlik olsun, sana yardım edenlere de esenlik olsun; çünkü Tanrın sana yardım ediyor.” Sonra David onları kabul etti ve onları çete başları yaptı."],["19","Manaşşe'den bazıları da David'in Filistliler'le birlikte Saul'a karşı savaşmak için geldiğinde David'e katıldılar, ama Filistliler'e yardım etmediler. Çünkü Filistliler'in beyleri, “Efendisi Saul'un yanına geçip başımızı tehlikeye sokacak” diyerek danıştıktan sonra onu gönderdiler."],["20","Ziklag'a gittiğinde, Manaşşe'den binlerin başları olan Adna, Yozavad, Yediael, Mikael, Yozavad, Elihu ve Silletay, Manaşşe'den ona katıldılar."],["21","Akıncılara karşı David'e yardım ettiler. Çünkü hepsi de cesur yiğitlerdi, ordu komutanlarıydı."],["22","Çünkü her gün David'e yardım etmek için adamlar geliyordu. Ta ki, Tanrı'nın ordusu gibi büyük bir ordu oluncaya dek."],["23","Yahve'nin sözüne göre, Saul'un krallığını David'e döndürmek için onun yanına, Hevron'a, gelen savaş için silahlanmış olanların başlarının sayıları şunlardır."],["24","Yahuda'nın çocuklarından kalkan ve mızrak taşıyanlar, savaş için silahlanmış altı bin sekiz yüz kişi."],["25","Şimon'un çocuklarından, savaş için cesur yiğitler, yedi bin yüz kişi."],["26","Levi'nin çocuklarından: Dört bin altı yüz kişi."],["27","Aron'un ev halkının önderi Yehoyada idi; onunla birlikte üç bin yedi yüz kişi."],["28","Cesur yiğit bir genç olan Sadok ve atası evinden yirmi iki komutan."],["29","Benyamin'in çocuklarından, Saul'un akrabaları: Üç bin, çünkü o zamana dek onların çoğu Saul'un evine bağlı kalmıştı."],["30","Efraim'in çocuklarından: Yirmi bin sekiz yüz, cesur yiğitler, ataları evlerinde ünlü adamlar."],["31","Manaşşe'nin yarım oymağından: David'i kral yapmak için gelip adlarıyla anılan on sekiz bin kişi."],["32","İssakar'ın çocuklarından, İsrael'in ne yapması gerektiğini bilmek için zamanların anlayışına sahip olanlar, onların başları iki yüz kişiydi; bütün kardeşleri de onların buyruğundaydı."],["33","Zevulun'dan, orduyla çıkabilen, her türlü savaş aletiyle savaş düzeni alabilen: Buyruk verilebilir ve çift yürekli olmayan elli bin kişi."],["34","Naftali'den: Bin komutan ve onlarla birlikte kalkan ve mızrakla otuz yedi bin kişi."],["35","Danlılar'dan, savaş düzeni alabilen: Yirmi sekiz bin altı yüz kişi."],["36","Aşer'den, orduyla çıkabilen, savaş düzeni alabilen: Kırk bin kişi."],["37","Yarden'in öte yakasında, Ruvenliler'den, Gadlılar'dan ve Manaşşe'nin yarım oymağından, savaş için her türlü savaş aletiyle: Yüz yirmi bin kişi."],["38","Bunların hepsi savaş düzenini bilen savaşçılardı ve David'i bütün İsrael'in üzerine kral yapmak için Hevron'a tam bir yürekle geldiler; İsrael'in geri kalanı da David'i kral yapmak için tek yürekti."],["39","Onlar David'le birlikte üç gün orada kaldılar, yiyip içtiler; çünkü kardeşleri onlara erzak sağlamıştı."],["40","İssakar, Zevulun ve Naftali'ye varıncaya kadar onlara yakın olanlar da, eşekler, develer, katırlar ve öküzler üzerinde ekmek getirdiler; un, basılmış incir, kuru üzüm salkımları, şarap, yağ, bol miktarda sığır ve koyun getirdiler; çünkü İsrael'de sevinç vardı."]],13:[["1","David binlerin, yüzlerin başlarıyla ve her önderle danıştı."],["2","David bütün İsrael topluluğuna şöyle dedi: “Eğer size iyi görünüyorsa ve bu Tanrımız Yahve'den ise, İsrael diyarında kalan kardeşlerimize, otlakları olan kentlerinde kâhinlerle Levililer'in bulunduğu her yere haber gönderelim de yanımıza toplansınlar."],["3","Tanrımız'ın Sandığı'nı da geri getirelim. Çünkü Saul zamanında onu aramadık.”"],["4","Bütün topluluk, öyle yaparız dediler; çünkü bütün halkın gözünde bu şey doğru idi."],["5","Bunun üzerine David bütün İsrael halkını, Mısır'ın Şihor Irmağı'ndan Hamat'ın girişine kadar, Tanrı'nın Sandığı'nı Kiryat Yearim'den getirmek üzere topladı."],["6","David, bütün İsrael'le birlikte, Tanrı Yahve'nin, Keruvlar'ın üstünde oturan ve Adıyla anılan sandığını, Baala'dan, Yahuda'nın Kiryat Yearim'inden çıkarmak için oraya çıktı."],["7","Tanrı'nın Sandığı'nı yeni bir arabaya bindirip Avinadav'ın evinden çıkardılar; Uzza ve Ahio da arabayı sürüyordu."],["8","David ve bütün İsrael, Tanrı'nın önünde bütün güçleriyle, ezgilerle, çenklerle, telli çalgılarla, teflerle, zillerle ve borularla oynuyorlardı."],["9","Kidon'un harman yerine geldiklerinde, Uzza elini uzatıp sandığı tuttu; çünkü öküzler tökezlemişti."],["10","Yahve'nin öfkesi Uzza'ya karşı alevlendi ve elini sandığa koyduğu için onu vurdu; ve orada Tanrı'nın önünde öldü."],["11","David hoşnut değildi, çünkü Yahve Uzza'ya karşı öfkelenmişti. O, o yere Perez Uzza dedi; bugüne dek öyle denir."],["12","David o gün Tanrı'dan korkup, “Tanrı'nın Sandığı'nı nasıl eve yanıma getireyim?” dedi."],["13","Bunun üzerine David sandığı kendisiyle birlikte David Kenti'ne götürmedi, ama onu Gadlı Oved Edom'un evine saptırıp götürdü."],["14","Tanrı'nın Sandığı Oved Edom'un ailesiyle birlikte evinde üç ay kaldı. Yahve, Oved Edom'un evini ve sahip olduğu her şeyi kutsadı."]],14:[["1","Sur Kralı Hiram, David'e haberciler ve ona ev yapmak için sedir ağaçları, duvarcılarla marangozlar gönderdi."],["2","David, Yahve'nin kendisini İsrael üzerine kral olarak pekiştirdiğini, çünkü halkı İsrael uğruna krallığını çok yükselttiğini anladı."],["3","David Yeruşalem'de daha çok karılar aldı ve David daha çok oğullar ve kızlar babası oldu."],["4","Yeruşalem'de olan çocuklarının adları şunlardır: Şammua, Şovav, Natan, Solomon,"],["5","İvhar, Elişua, Elpelet,"],["6","Nogah, Nefeg, Yafia,"],["7","Elişama, Beeliada ve Elifelet."],["8","Filistliler, David'in bütün İsrael üzerine kral olarak meshedildiğini duyunca, Filistliler'in tümü David'i aramaya çıktılar. David de bunu duyunca onlara karşı çıktı."],["9","Filistliler gelip Refaim Vadisi'ne baskın yapmışlardı."],["10","David Tanrı'ya sorup şöyle dedi, “Filistliler'e karşı çıkayım mı? Onları elime teslim edecek misin?” Yahve ona, “Çık, çünkü onları senin eline teslim edeceğim” dedi."],["11","Bunun üzerine Baal Perazim'e çıktılar ve David onları orada yendi. David, “Suların yarıldığı gibi, Tanrı düşmanlarımı elimle kırdı” dedi. Bu yüzden o yerin adını Baal Perazim koydular."],["12","Onlar ilâhlarını orada bıraktılar ve David buyruk verdi ve onlar ateşle yakıldı."],["13","Filistliler vadide bir baskın daha yaptılar."],["14","David Tanrı'ya yine sordu ve Tanrı ona, “Onların peşinden çıkmayacaksın. Onlardan dön ve dut ağaçlarının karşısında onların üzerine gel.” dedi."],["15","“Dut ağaçlarının tepelerinde yürüyüş sesi duyduğunda savaşa çık; çünkü Tanrı Filist ordusunu vurmak için senden önce çıkmıştır.”"],["16","David Tanrı'nın kendisine buyurduğu gibi yaptı ve Filist ordusuna Givon'dan Gezer'e kadar saldırdılar."],["17","David'in ünü bütün ülkelere yayıldı ve Yahve bütün ulusların üzerine onun korkusunu getirdi."]],15:[["1","David, kendisi için David Kenti'nde evler yaptı; Tanrı'nın Sandığı için bir yer hazırladı ve onun için bir çadır kurdu."],["2","David, “Tanrı'nın Sandığı'nı Levililer'den başkası taşımamalı. Çünkü Yahve, Tanrı'nın Sandığı'nı taşımak ve daima kendisine hizmet etmek için onları seçti.” dedi."],["3","David, Yahve'nin Sandığı'nı hazırladığı yere çıkarmak için bütün İsrael'i Yeruşalem'de topladı."],["4","David, Aron'un oğullarını ve Levililer'i topladı:"],["5","Kohatoğulları'nın başı Uriel ve kardeşleri yüz yirmi kişi;"],["6","Merari oğullarının başı Asaya ve kardeşleri iki yüz yirmi kişi;"],["7","Gerşom oğullarının başı Yoel ve kardeşleri yüz otuz kişi;"],["8","Elizafan oğullarının başı Şemaya ve kardeşleri iki yüz kişi;"],["9","Hevron oğullarının başı Eliel ve kardeşleri seksen kişi;"],["10","Uzziel oğullarının başı Amminadav ve kardeşleri yüz on iki kişi."],["11","David, kâhinleri, Sadok'u ve Aviyatar'ı ve Levililer'i, Uriel, Asaya, Yoel, Şemaya, Eliel ve Amminadav'ı çağırdı."],["12","Onlara, “Siz Levililer'in atalar evlerinin başlarısınız. Siz ve kardeşleriniz, İsrael'in Tanrısı Yahve'nin Sandığı'nı onun için hazırlamış olduğum yere çıkarmak için kendinizi kutsayın.” dedi."],["13","“Çünkü siz onu ilk başta taşımadığınız için, Tanrımız Yahve bize karşı öfkeyle çıkıştı; çünkü biz O'nun kuralına göre aramadık.”"],["14","Böylece kâhinler ve Levililer, İsrael'in Tanrısı Yahve'nin Sandığı'nı çıkarmak için kendilerini kutsadılar."],["15","Levililer'in çocukları, Yahve'nin sözüne göre Moşe'nin buyurduğu gibi, Tanrı'nın Sandığı'nı sırıklarıyla omuzları üzerinde taşıdılar."],["16","David, Levililer'in başına, müzik aletleri, telli çalgılar, çenkler ve zillerle, sevinçle ses yükselten ezgi söyleyenleri kardeşlerinden atasın diye söyledi."],["17","Böylece Levililer, Yoel oğlu Heman'ı, kardeşlerinden Berekya oğlu Asaf'ı, Merarioğulları'ndan kardeşleri Kuşaya oğlu Etan'ı,"],["18","ve onlarla birlikte ikinci sıradaki kardeşlerinden kapıcıları Zekariya, Ben, Yaaziel, Şemiramot, Yehiel, Unni, Eliav, Benaya, Maaseya, Mattitya, Elifelehu, Mikneya, Oved Edom ve Yeiel'i atadılar."],["19","Böylece ezgi söyleyenler, Heman, Asaf ve Etan'a yüksek sesle çalmaları için tunç ziller verildi;"],["20","Zekariya, Aziel, Şemiramot, Yehiel, Unni, Eliav, Maaseya ve Benaya telli çalgılarla Alamot'a;"],["21","Matitya, Elifelehu, Mikneya, Oved Edom, Yeiel ve Azaziya ise sekiz telli lire göre ayarlanmış çenklerle önderlik etsinler diye atandılar."],["22","Levililer'in başı Kenanya ezgiyi yönetiyordu. Yetenekli olduğu için ezgicilere o öğretiyordu."],["23","Berekya ve Elkana sandık için kapıcılardı."],["24","Şevanya, Yoşafat, Netanel, Amasay, Zekariya, Benaya ve Eliezer, kâhinler, Tanrı'nın Sandığı önünde boruları çalıyorlardı; Oved Edom ve Yehiya sandık için kapıcı idiler."],["25","Böylece David, İsrael'in ihtiyarları ve binlerin başları, sevinçle Yahve'nin Antlaşma Sandığı'nı Oved Edom'un evinden yukarı çıkarmak için gittiler."],["26","Tanrı, Yahve'nin Antlaşma Sandığı'nı taşıyan Levililer'e yardım edince, yedi boğa ve yedi koç kurban ettiler."],["27","David ince ketenden bir cübbe giymişti, sandığı taşıyan bütün Levililer, ezgi söyleyenlerle birlikte koro şefi Kenanya da öyle. David'in üzerinde keten bir efod vardı."],["28","Böylece bütün İsrael, bağırışla, zurna sesiyle, borular ve zillerle, yüksek ses çıkaran telli çalgılar ve çenkler çalarak Yahve'nin Antlaşma Sandığı'nı yukarı çıkardılar."],["29","Yahve'nin Antlaşma Sandığı David'in kentine geldiğinde, Saul'un kızı Mikal pencereden baktı ve Kral David'in dans edip oynadığını gördü; ve yüreğinde onu küçümsedi."]],16:[["1","Tanrı'nın Sandığı'nı içeri getirip David'in onun için kurmuş olduğu çadırın ortasına koydular. Tanrı'nın önünde yakmalık sunular ve esenlik sunuları sundular."],["2","David yakmalık sunuyu ve esenlik sunularını sunmayı bitirince, halkı Yahve'nin adıyla kutsadı."],["3","İsraelliler'in her birine, hem erkek hem de kadın, herkese birer somun ekmek, birer parça et ve birer kuru üzüm pestili verdi."],["4","Levililer'den bazılarını Yahve'nin Sandığı önünde hizmet etmek, İsrael'in Tanrısı Yahve'yi anmak, O'na şükretmek ve O'nu övmek için atadı:"],["5","Baş Asaf, onun ikincisi olan Zekariya, sonra Yeiel, Şemiramot, Yehiel, Mattitya, Eliav, Benaya, Obed Edom ve Yeiel, telli çalgılar ve çenklerle; Asaf da yüksek ses çıkaran zillerle;"],["6","Benaya ve Yahaziel kâhinler, sürekli olarak, Tanrı'nın Antlaşma Sandığı'nın önünde borularla."],["7","O zaman David, ilk olarak o gün Asaf ve kardeşleri eli aracılığıyla Yahve'ye şükretme işini verdi."],["8","Yahve'ye şükredin. Adını çağırın. Yaptıklarını halklar arasında bildirin."],["9","O'na ezgiler söyleyin. O'na övgüler sunun. Bütün şaşılası işlerini anlatın."],["10","Kutsal adıyla övünün. Yahve'yi arayanların yüreği sevinsin."],["11","Yahve'yi ve O'nun gücünü arayın. Daima O'nun yüzünü arayın."],["12","O'nun yaptığı şaşılası işlerini, O'nun harikalarını ve ağzının hükümlerini hatırlayın,"],["13","Ey hizmetkârı İsrael'in soyu, ey seçilmişleri, Yakov'un çocukları."],["14","O, Tanrımız Yahve'dir. Hükümleri bütün yeryüzündedir."],["15","Sonsuza dek antlaşmasını, bin kuşağa kadar buyurduğu sözünü,"],["16","Avraham'la yaptığı antlaşmayı, İshak'a olan andını hatırlayın."],["17","Bunu Yakov'a bir yasa olarak, İsrael'e de ebedi bir antlaşma olarak onayladı."],["18","“Size Kenan diyarını, mirasınızın payı olmak üzere vereceğim” dedi."],["19","Siz sayıca az, evet, çok az ve orada yabancıyken,"],["20","ulustan ulusa, bir krallıktan başka bir halka dolaştınız."],["21","Hiç kimsenin onlara kötülük etmesine izin vermedi. Evet, kralları onlar uğruna azarladı."],["22","“Meshedilmişlerime dokunmayın! Peygamberlerime kötülük etmeyin!”"],["23","Ey bütün dünya, Yahve'ye ezgi söyleyin! Kurtarışını her gün gösterin."],["24","Uluslar arasında görkemini, bütün halklar arasında şaşılası işlerini duyurun."],["25","Çünkü Yahve büyüktür ve övgüye çok layıktır. Bütün ilâhlardan çok da O'ndan korkulmalıdır."],["26","Çünkü halkların bütün ilâhları putlardır, ancak gökleri yaratan Yahve'dir."],["27","O'nun önünde onur ve görkem vardır. Güç ve sevinç O'nun bulunduğu yerdedir."],["28","Ey halkların soyları, Yahve'ye verin, yüceliği ve gücü Yahve'ye verin!"],["29","Yahve'ye adına yaraşır görkemi verin. Sunu getirin ve O'nun önüne çıkın. Kutsal giysiler içinde Yahve'ye tapının."],["30","Ey bütün dünya O'nun önünde titreyin. Dünya da kurulmuştur, sarsılamaz."],["31","Gökler sevinsin, yeryüzü coşsun! Uluslar arasında, “Yahve hüküm sürüyor!” desinler."],["32","Deniz ve onun doluluğu gürlesin! Kırlar ve içindekilerin hepsi sevinçle coşsun!"],["33","Orman ağaçları Yahve'nin önünde sevinçle ezgi söyleyecekler, çünkü O yeryüzüne hükmetmeye geliyor."],["34","Yahve'ye şükredin, çünkü O iyidir, çünkü O'nun sevgi dolu iyiliği sonsuza dek sürer."],["35","Söyleyip deyin, “Kurtar bizi, kurtuluşumuzun Tanrısı! Bizi bir araya topla ve uluslardan kurtar, senin kutsal adına şükretmek, övgünle övünmek için.”"],["36","İsrael'in Tanrısı Yahve, sonsuzluktan sonsuza dek övülsün. Bütün halk, “Amin” dedi ve Yahve'ye övgüler sundu."],["37","Bunun üzerine Asaf'ı ve kardeşlerini, her günkü işlerin gerektirdiği gibi, sürekli olarak sandığın önünde hizmet etsinler diye, Yahve'nin Antlaşma Sandığı'nın önünde;"],["38","ve Obed Edom'u ve altmış sekiz akrabasını; Yedutun oğlu Obed Edom'u ve Hosa'yı kapı bekçisi olarak bıraktı;"],["39","ve kâhin Sadok'u ve kâhin kardeşlerini, Givon'daki yüksek yerde bulunan Yahve'nin çadırının önünde;"],["40","Yahve'ye yakmalık sunular sunağında, Yahve'nin İsrael'e buyurduğu yasada yazılı olan her şeye göre, her sabah ve akşam sürekli olarak yakmalık sunular sunmak için;"],["41","ve onlarla birlikte Heman'ı, Yedutun'u ve adları anılan seçilmiş geri kalanları bıraktı, Yahve'ye şükretmek için, çünkü O'nun sevgi dolu iyiliği sonsuza dek sürer;"],["42","ve onlarla birlikte Heman ve Yedutun da; yüksek ses çıkaranlara borular ve ziller, ve Tanrı'nın ezgileri için çalgılar verdi, kapıda olmak üzere Yedut'un oğullarını da orada bıraktı."],["43","Bütün halk, her biri kendi evine gitti; David de evini kutsamak için geri döndü."]],17:[["1","David evinde yaşarken, David Peygamber Natan'a, “Ben sedirden yapılmış bir evde oturuyorum, ama Yahve'nin Antlaşma Sandığı bir çadırda” dedi."],["2","Natan David'e, “Yüreğinde olan her şeyi yap, çünkü Tanrı seninledir” dedi."],["3","O gece Tanrı'nın sözü Natan'a geldi ve şöyle dedi,"],["4","“Git, hizmetkârım David'e söyle, 'Yahve şöyle diyor, “Bana oturmak için sen bana ev yapmayacaksın."],["5","Çünkü İsrael'i çıkardığım günden bu güne dek bir evde yaşamadım, çadırdan çadıra, bir çadırdan öbürüne dolaştım."],["6","Bütün İsrael'le birlikte yürüdüğüm yerlerin hepsinde, halkımın çobanı olmalarını buyurduğum İsrael hâkimlerinden herhangi birine, 'Neden bana sedirden bir ev yapmadınız?' diye bir söz söyledim mi?”'”"],["7","“Şimdi, hizmetkârım David'e şöyle diyeceksin: 'Ordular Yahvesi şöyle diyor, “Halkım İsrael'in üzerine hükümdar olmak üzere seni koyun ağılından, koyunların ardından aldım."],["8","Gittiğin her yerde seninle oldum, önünden bütün düşmanlarını söküp attım. Yeryüzündeki büyüklerin adı gibi sana bir ad yapacağım."],["9","Halkım İsrael için bir yer belirleyeceğim, onları dikeceğim, kendi yerlerinde oturacaklar ve bir daha yerinden oynatılmayacaklar. İlk başta olduğu gibi,"],["10","ve halkım İsrael'in üzerine hâkimler buyurduğum günden beri olduğu gibi, kötülüğün çocukları onları bir daha harap etmeyecek. Bütün düşmanlarına boyun eğdireceğim. Yahve'nin sana bir ev yapacağını da sana bildiriyorum."],["11","Öyle olacak ki, senin günlerin dolup atalarınla birlikte olmak üzere gitmen gerektiğinde, senden sonra oğullarından olacak soyunu durduracağım ve onun krallığını pekiştireceğim."],["12","O bana ev yapacak ve onun tahtını sonsuza dek pekiştireceğim."],["13","Ben onun babası olacağım ve o da benim oğlum olacak. Senden öncekinden geri aldığım gibi, sevgi dolu iyiliğimi ondan geri almayacağım."],["14","Ama onu sonsuza dek evimde ve krallığımda yerleştireceğim. Tahtı sonsuza dek pekiştirilecektir.”'”"],["15","Bütün bu sözlere ve bütün bu görüme göre, Natan David’e böyle söyledi."],["16","O zaman Kral David içeri girip Yahve'nin önünde oturdu ve şöyle dedi, “Ben kimim, Ey Yahve Tanrı, evim nedir ki, beni buraya kadar getirdin?"],["17","Ey Tanrım, bu senin gözünde küçük bir şeydi, ama hizmetkârının evinden uzun bir süre için söz ettin ve bana yüksek bir adammışım gibi saygı gösterdin, ey Yahve Tanrı."],["18","David, hizmetkârına verilen bu saygınlıkla ilgili sana daha ne diyebilir? Çünkü hizmetkârını bilirsin."],["19","Ey Yahve, hizmetkârının hatırı için ve senin kendi yüreğine göre, bütün bu büyük şeyleri bildirmek için bütün bu büyüklüğü yaptın."],["20","Ey Yahve, kulaklarımızla duyduğumuz her şeye göre senin gibisi yoktur, senden başka Tanrı da yoktur."],["21","Kendi halkının önünden ulusları kovarak, büyük ve korkunç şeylerle kendine isim yapmak için, Mısır'dan fidye ile kurtardığın halkın İsrael gibi, yeryüzünde hangi ulus var ki, Tanrı onu kendisine halk olması için kurtarmaya gitmiştir?"],["22","Çünkü halkın İsrael'i sonsuza dek kendi halkın yaptın ve sen, ey Yahve, onların Tanrısı oldun."],["23","Şimdi, ey Yahve, hizmetkârın ve onun evi hakkında söylediğin söz sonsuza dek sabit olsun ve söylediğin gibi yap."],["24","'Ordular Yahvesi, İsrael'in Tanrısı'dır, İsrael'e Tanrı'dır' denilip adın sonsuza dek sabit olsun ve yüceltilsin, 'Hizmetkârın David'in evi senin önünde sabit olsun.'"],["25","Çünkü sen, Tanrım, hizmetkârına bir ev yapacağını açığa vurdun. Bu nedenle hizmetkârın önünde dua etme cesaretini buldu."],["26","Şimdi, ey Yahve, sen Tanrı'sın ve hizmetkârına bu iyi şeyi vaat ettin."],["27","Şimdi, hizmetkârının evini daima önünde sürsün diye kutsamak seni hoşnut etti; çünkü sen, ey Yahve, kutsadın ve sonsuza dek kutsandı."]],18:[["1","Bundan sonra David Filistliler'i yendi ve onlara boyun eğdirdi ve Gat'ı ve kasabalarını Filistliler'in elinden aldı."],["2","Moav'ı yendi; Moavlılar David'e vergi ödeyen hizmetkârlar oldular."],["3","David, Fırat Irmağı yanındaki hakimiyetini kurmak için giderken, Hamat'a doğru, Sova Kralı Hadadezer'i yendi."],["4","David ondan bin savaş arabası, yedi bin atlı ve yirmi bin yaya asker aldı; David bütün savaş arabalarının atlarını sakatladı, ancak bunlardan yüz savaş arabasına yetecek kadarını ayırdı."],["5","Damaskuslu Suriyeliler Sova Kralı Hadadezer'e yardım etmeye geldiklerinde, David Suriyeliler'den yirmi iki bin kişiyi vurdu."],["6","Sonra David Suriye'nin Damaskus'unda askeri birlikler koydu; Suriyeliler David'e hizmetkâr oldular ve vergi ödediler. Yahve David'in gittiği her yerde ona zafer verdi."],["7","David, Hadadezer'in hizmetkârlarının üzerindeki altın kalkanları alıp Yeruşalem'e getirdi."],["8","Hadadezer'in kentleri olan Tivhat ve Kun'dan David çok miktarda tunç aldı. Solomon bunlarla tunç denizi, direkleri ve tunç kapları yaptı."],["9","Hamat Kralı Tou, David'in Sova Kralı Hadadezer'in bütün ordusunu vurduğunu duyunca,"],["10","oğlu Hadoram'ı David'i selamlamak ve kutsamak için ona gönderdi; çünkü Hadadezer'e karşı savaşmış ve onu vurmuştu (çünkü Hadadezer'in, Tou ile savaşları vardı); yanında da her çeşit altın, gümüş ve tunç kaplar vardı."],["11","Kral David de, bütün bu uluslardan Edom'dan, Moav'dan, Ammon'un çocuklarından, Filistliler'den ve Amalek'ten getirmiş olduğu gümüş ve altınla birlikte bunları Yahve'ye adadı."],["12","Seruya oğlu Avişay da, Tuz Vadisi'nde Edomlular'dan on sekiz bin kişiyi vurdu."],["13","Edom'a askeri birlikler koydu ve bütün Edomlular David'in hizmetkârları oldular. Yahve, David'in gittiği her yerde ona zafer verdi."],["14","David bütün İsrael üzerinde hüküm sürdü ve halkının tümüne adalet ve doğruluk sağladı."],["15","Seruya oğlu Yoav ordu komutanıydı; Ahilud oğlu Yehoşafat tarihçiydi;"],["16","Ahituv oğlu Sadok ve Aviyatar oğlu Avimelek kâhinlerdi; Şavşa kâtipti;"],["17","Yehoyada oğlu Benaya Keretiler ve Peletliler'in başındaydı; David'in oğulları ise krala hizmet eden baş görevlilerdi."]],19:[["1","Bundan sonra Ammon'un çocuklarının kralı Nahaş öldü ve yerine oğlu kral oldu."],["2","David, “Babası bana iyilik ettiği için ben de Nahaş oğlu Hanun’a iyilik edeceğim” dedi. Bunun üzerine David, babasıyla ilgili olarak onu teselli etmek için ulaklar gönderdi. David’in hizmetkârları, onu teselli etmek için Ammon'un çocuklarının ülkesine, Hanun’un yanına vardılar."],["3","Ama Ammon'un çocuklarının beyleri Hanun’a, “David’in sana teselliciler göndererek babanı onurlandırdığını mı sanıyorsun? Hizmetkârları sana gelip ülkeyi araştırmak, devirmek ve casusluk yapmak için gelmediler mi?” dediler."],["4","Bunun üzerine Hanun, David'in hizmetkârlarını aldı, onları tıraş etti ve giysilerini kalçalarının ortasından kesip gönderdi."],["5","O zaman bazı kişiler gidip David’e adamlara nasıl davranıldığını anlattılar. David onları karşılamak için adam gönderdi; çünkü adamlar çok aşağılanmışlardı. Kral, “Sakallarınız uzayıncaya dek Yeriha’da kalın, sonra dönün” dedi."],["6","Ammon'un çocukları, David’e karşı kendilerini iğrenç ettiklerini görünce, Hanun ve Ammon'un çocukları, Mezopotamya’dan, Aram Maaka’dan ve Sova’dan savaş arabaları ve atlılar tutmak için bin talant gümüş gönderdiler."],["7","Böylece kendileri için otuz iki bin savaş arabası ve Maaka Kralı'nı ve adamlarını ücretli tuttular. Onlar da gelip Medeva’nın yakınında ordugâh kurdu. Ammon'un çocukları kentlerden toplanıp savaşa geldiler."],["8","David bunu duyunca, Yoav’ı ve bütün yiğitler ordusunu gönderdi."],["9","Ammon'un çocukları çıkıp kentin kapısında savaş düzenine koyuldular. Gelen krallar ise ayrı olarak kırdaydılar."],["10","Yoav, savaşın önünde ve arkasında kendisine karşı olduğunu görünce, İsrael'in seçme adamlarından bazılarını ayırıp onları Suriyeliler'e karşı dizdi."],["11","Halkın geri kalanını kardeşi Avişay'ın eline teslim etti, onlar da Ammon'un çocuklarına karşı dizildiler."],["12","Şöyle dedi: “Eğer Suriyeliler benden güçlü çıkarsa, o zaman bana yardım edeceksiniz; ama eğer Ammon'un çocukları sizden güçlü çıkarsa, o zaman ben size yardım edeceğim."],["13","Cesur olun ve halkımız ve Tanrımız'ın kentleri için güçlü olalım. Yahve kendisine iyi görüneni yapsın.”"],["14","Böylece Yoav ve yanındaki halk, savaş için Suriyeliler'in önüne yaklaştılar; onlar da onun önünden kaçtılar."],["15","Ammon'un çocukları, Suriyeliler'in kaçtığını görünce, onlar da kardeşi Avişay'ın önünden kaçıp kente girdiler. O zaman Yoav Yeruşalem'e geldi."],["16","Suriyeliler İsrael tarafından yenildiklerini görünce, ulaklar gönderip, Hadadezer'in ordusunun başkomutanı Şofak'ın önderliğinde, Irmak ötesindeki Suriyeliler'i çağırdılar."],["17","David bunu duyunca, bütün İsrael'i topladı, Yarden'i geçti, onlara geldi ve onlara karşı savaş düzeni aldı. Böylece David Suriyeliler'e karşı savaş düzeni aldığında, onunla savaştılar."],["18","Suriyeliler İsrael'in önünden kaçtılar; David Suriyeliler'den yedi bin arabacı ve kırk bin yaya asker öldürdü, ordunun başkomutanı Şofak'ı da öldürdü."],["19","Hadadezer'in hizmetkârları İsrael tarafından yenildiklerini görünce, David'le barış yaptılar ve ona hizmet ettiler. Suriyeliler artık Ammon'un çocuklarına yardım etmediler."]],20:[["1","Yıl dönümünde, kralların dışarı çıktığı zaman, Yoav orduyu çıkardı ve Ammon'un çocuklarının ülkesini harap etti ve gelip Rabba'yı kuşattı. Ama David Yeruşalem'de kaldı. Yoav Rabba'yı vurdu ve onu yıktı."],["2","David krallarının tacını başından aldı ve onu bir talant altın ağırlığında buldu, içinde değerli taşlar vardı. David'in başına konuldu ve kentten çok miktarda ganimet çıkardı."],["3","İçinde bulunan halkı dışarı çıkardı ve onları testerelere, demir kazmalara ve baltalara koydurdu. David Ammon'un çocuklarının bütün kentlerine böyle yaptı. Sonra David ve bütün halk Yeruşalem'e döndü."],["4","Bundan sonra Gezer'de Filistliler'le savaş çıktı. Sonra Huşatlı Sibbekay dev oğullarından Sippay'ı öldürdü, onlar da boyun eğdiler."],["5","Filistliler'le yine savaş çıktı; ve Yair oğlu Elhanan, Gatlı Golyat'ın kardeşi Lahmi'yi öldürdü. Mızrağının sapı dokumacı sırığı gibiydi."],["6","Gat'ta yine savaş çıktı. Orada iri yapılı bir adam vardı. Adamın her elinde altı, her ayağında altı olmak üzere yirmi dört parmağı vardı. O da deve doğmuştu."],["7","İsrael'e meydan okuyunca, David'in kardeşi Şimea'nın oğlu Yonatan onu öldürdü."],["8","Bunlar Gat'taki deve doğmuşlardı. David'in ve hizmetkârlarının eliyle düştüler."]],21:[["1","Şeytan İsrael'e karşı çıktı ve David'i İsrael'i saymak için harekete geçirdi."],["2","David Yoav'a ve halkın beylerine, “Gidin, İsrael'i Beerşeva'dan Dan'a kadar sayın; bana haber getirin de kaç kişi olduğunu bileyim” dedi."],["3","Yoav, “Yahve halkını olduklarından yüz kat daha çoğaltsın” dedi. “Ama efendim kral, onların hepsi efendimin hizmetkârları değil mi? Efendim neden bu şeyi istiyor? Neden İsrael'e suç getirtsin?”"],["4","Yine de kralın sözü Yoav'a karşı üstün geldi. Bunun üzerine Yoav ayrılıp bütün İsrael'i dolaştıktan sonra Yeruşalem'e geldi."],["5","Yoav halkın yazılan sayısını David'e verdi. İsrael'in hepsi kılıç çeken bir milyon yüz bin kişiydi; Yahuda'da ise kılıç çeken dört yüz yetmiş bin kişi vardı."],["6","Ama Levi ve Benyamin'i onların arasında saymadı, çünkü kralın sözü Yoav'a iğrenç geldi."],["7","Tanrı bu şeyden hoşnut değildi ve bu yüzden İsrael'i vurdu."],["8","David Tanrı'ya, “Bu işi yapmakla büyük günah işledim” dedi, “Ama şimdi yalvarırım, hizmetkârının suçunu kaldır, çünkü çok akılsızlık ettim.”"],["9","Yahve, David'in Gören'i Gad'a şöyle dedi:"],["10","“Git, David'e söyle, 'Yahve şöyle diyor, “Sana üç şey sunuyorum. Bunlardan birini seç de sana onu yapayım.'””"],["11","Gad David'in yanına geldi ve ona şöyle dedi: “Yahve şöyle diyor, 'Seçimini yap:"],["12","Ya üç yıl kıtlık; ya da düşmanlarının kılıcı seni yakalarken düşmanlarının önünde üç ay bitip tükenmek; ya da, üç gün Yahve'nin kılıcı, Yahve'nin meleğinin İsrael'in bütün sınırlarındaki yıkımı, ülkede veba. Şimdi bu nedenle beni gönderene ne yanıt götüreceğimi düşün.'”"],["13","David Gad'a, “Sıkıntıdayım” dedi, “Duacıyım, Yahve'nin eline düşeyim, çünkü O'nun merhametleri çok büyüktür. İnsan eline düşmeyeyim.”"],["14","Bunun üzerine Yahve İsrael'in üzerine veba gönderdi ve İsrael'den yetmiş bin kişi düştü."],["15","Tanrı, Yeruşalem'i yok etmek için bir melek gönderdi. Onu yok etmek üzereyken Yahve gördü ve felaketten vazgeçti ve yok edici meleğe, “Yeter artık. Şimdi elini çek.” dedi. Yahve'nin meleği, Yevuslu Ornan'ın harman yerinin yanında duruyordu."],["16","David gözlerini kaldırdı ve elinde çekilmiş bir kılıçla Yeruşalem üzerine uzatmış, yeryüzüyle gökyüzü arasında duran Yahve'nin meleğini gördü. O zaman çul giymiş olan David ve ihtiyarlar yüzüstü yere kapandılar."],["17","David Tanrı'ya, “Halkın sayılmasını buyuran ben değil miyim? Günah işleyen ve çok kötülük eden benim. Ama bu koyunlar ne yaptılar? Lütfen, ey Tanrım Yahve, elin bana ve babamın evine karşı olsun; ama kendi halkını cezalandırmak için onlara karşı olmasın.” dedi."],["18","O zaman Yahve'nin meleği Gad'a, David'e çıkıp Yevuslu Ornan'ın harman yerinde Yahve'ye bir sunak kurmasını söylemesini buyurdu."],["19","David, Yahve'nin adıyla söylediği Gad'ın sözü üzerine yukarı çıktı."],["20","Ornan arkasına döndü ve meleği gördü; ve kendisiyle birlikte olan dört oğlu saklandılar. Ornan buğday dövüyordu."],["21","David Ornan'ın yanına gelince, Ornan baktı ve David'i gördü, harman yerinden çıktı ve yüzüstü yere kapanıp David'in önünde eğildi."],["22","David Ornan'a, “Bu harman yerinin yerini bana sat da üzerinde Yahve'ye bir sunak yapayım. Bana tam değeriyle satacaksın ki, veba halkın üzerinden kalksın.” dedi."],["23","Ornan David'e, “Onu kendine al, efendim kral gözünde iyi olanı yapsın. İşte, yakmalık sunular için öküzleri, odun için dövenleri ve ekmek sunusu için buğdayı veriyorum. Hepsini veriyorum.” dedi."],["24","Kral David Ornan'a, “Hayır, ama kesinlikle tam değeriyle satın alacağım” dedi. “Çünkü senin olanı Yahve için almam, bana hiçe mal olmuş yakmalık sunu sunmam.”"],["25","Bunun üzerine David, Ornan'a yer için ağırlıkta altı yüz şekel altın verdi."],["26","David orada Yahve'ye bir sunak yaptı, yakmalık sunularını ve esenlik sunularını sundu ve Yahve'yi çağırdı. Yahve de yakmalık sunu sunağı üzerinde gökyüzünden ateşle ona yanıt verdi."],["27","O zaman Yahve meleğe buyurdu, o da kılıcını kınına koydu."],["28","O sırada David, Yahve'nin kendisine Yevuslu Ornan'ın harman yerinde yanıt verdiğini görünce, orada kurban kesti."],["29","Çünkü Moşe'nin çölde yaptığı Yahve'nin çadırı ve yakmalık sunu sunağı o sırada Givon'daki yüksek yerdeydi."],["30","Ama David, Tanrı'dan sormak için O'nun önüne gidemedi; çünkü Yahve'nin meleğinin kılıcı yüzünden korkuyordu."]],22:[["1","O zaman David, “Bu, Tanrı Yahve'nin evidir, İsrael için yakmalık sunu sunağı da budur” dedi."],["2","David, İsrael ülkesinde bulunan yabancıların toplanmasını buyurdu ve Tanrı'nın evini yapmak için yontma taşlar kesmeleri için duvarcıları koydu."],["3","David, kapıların çivileri ve bağlantı parçaları için bol miktarda demir, çoklukta tartılamaz miktarda tunç ve sayısız sedir ağacı hazırladı."],["4","Saydalılar ve Sur halkı David'e bol miktarda sedir ağacı getirdiler."],["5","David, “Oğlum Solomon genç ve toydur” dedi. “Yahve için yapılacak ev çok büyük, bütün ülkelerde ünlü ve görkemli olmalı. Bu nedenle onun için hazırlık yapacağım.” Böylece David ölümünden önce bolca hazırlık yaptı."],["6","Sonra oğlu Solomon'u çağırdı ve ona İsrael'in Tanrısı Yahve için bir ev yapmasını buyurdu."],["7","David oğlu Solomon'a şöyle dedi, “Ben kendim, Tanrım Yahve'nin adına bir ev yapmak yüreğimde vardı."],["8","Ama Yahve'nin sözü bana geldi ve şöyle dedi: Sen çok kan döktün ve büyük savaşlar yaptın. Adıma bir ev yapmayacaksın, çünkü gözümün önünde yeryüzünde çok kan döktün."],["9","İşte, sana bir oğul doğacak, o barış adamı olacak. Ona çevresindeki bütün düşmanlarından rahat vereceğim; çünkü onun adı Solomon olacak ve İsrael'e onun günlerinde barış ve huzur vereceğim."],["10","Adıma ev yapacak olan odur; ve o bana oğul olacak, ben ona baba olacağım; ve İsrael üzerinde krallığının tahtını sonsuza dek pekiştireceğim."],["11","Şimdi oğlum, Yahve seninle birlikte olsun ve seni başarılı kılsın ve Tanrın Yahve'nin evini, senin hakkında söylediği gibi yap."],["12","Yahve sana sağduyu ve anlayış versin ve seni İsrael'in başına koysun, öyle ki Tanrın Yahve'nin yasasını tutasın."],["13","Yahve'nin Moşe'ye İsrael hakkında verdiği kuralları ve ilkeleri yapmak üzere onları tutarsan, o zaman başarılı olacaksın. Güçlü ve cesur ol. Korkma ve yılgınlığa düşme."],["14","Şimdi, işte, sıkıntım içinde Yahve'nin evi için yüz bin talant altın, bir milyon talant gümüş, tartısız tunç ve demir hazırladım; çünkü bol miktardadır. Kereste ve taş da hazırladım; sen de bunlara ekleyebilirsin."],["15","Yanında çok sayıda işçi de var; taş ve kereste kesen işçiler ve her türlü işte becerikli her çeşit adam var;"],["16","altının, gümüşün, tunçun ve demirin sayısı yoktur. Kalk da yap, Yahve seninle birlikte olsun.”"],["17","David İsrael'in bütün beylerine de oğlu Solomon'a yardım etmelerini buyurup dedi,"],["18","“Tanrınız Yahve sizinle birlikte değil mi? Her yandan size rahat vermedi mi? Çünkü ülkenin sakinlerini benim elime teslim etti; ülke Yahve'nin ve halkının önünde boyun eğdi."],["19","Şimdi yüreğinizle ve canınızla Tanrınız Yahve'yi izlemeye koyulun. Bu yüzden kalkın ve Yahve'nin Antlaşma Sandığı'nı ve Tanrı'nın kutsal kaplarını Yahve'nin adına bina edilecek evin içine getirmek için Yahve Tanrı'nın kutsal yerini bina edin .”"]],23:[["1","David yaşlanmış ve günlere doymuştu. Oğlu Solomon'u İsrael üzerine kral yaptı."],["2","İsrael'in bütün beylerini, kâhinleri ve Levililer'i bir araya topladı."],["3","Otuz yaş ve ondan yukarı olan Levililer sayıldı. Onların birer birer sayısı otuz sekiz bin erkekti."],["4","David, “Bunlardan yirmi dört bini Yahve'nin evinin işine bakmak içindi, altı bini memur ve hâkimdi,"],["5","dört bini kapı bekçisi ve dört bini de övgü sunmak için yaptığım aletlerle Yahve'yi övecek” dedi."],["6","David onları Levi'nin oğullarına göre takımlara ayırdı: Gerşon, Kehat ve Merari."],["7","Gerşonlular'dan: Ladan ve Şimei."],["8","Ladan'ın oğulları: Baş Yehiel, Zetam ve Yoel, üç kişi."],["9","Şimei'nin oğulları: Şelomit, Haziel ve Haran, üç kişi. Bunlar Ladan'ın atalar evlerinin başlarıydı."],["10","Şimei'nin oğulları: Yahat, Sina, Yeuş ve Beria. Bu dördü Şimei'nin oğullarıydı."],["11","Baş Yahat, ikincisi Ziza idi; ama Yeuş ve Beria'nın çok sayıda oğlu yoktu; bu yüzden bir sayıda ata evi oldular."],["12","Kohat'ın oğulları: Amram, Yisthar, Hevron ve Uzziel, dört kişi."],["13","Amram'ın oğulları: Aron ve Moşe; ve Aron, kendisi ve oğulları daima en kutsal şeyleri kutsal kılsınlar, Yahve'nin önünde buhur yaksınlar, O'na hizmet etsinler ve daima O'nun adıyla kutsasınlar diye ayrılmıştı."],["14","Ama Tanrı adamı Moşe'ye gelince, oğulları Levi oymağı arasında sayıldılar."],["15","Moşe'nin oğulları: Gerşom ve Eliezer."],["16","Gerşom'un oğulları: Baş Şevuel."],["17","Eliezer'in oğlu baş Rehavya'ydı. Eliezer'in başka oğlu yoktu. Ama Rehavya'nın oğulları çoktu."],["18","Yitshar'ın oğulları: Baş Şelomit."],["19","Hevron'un oğulları: Baş Yeriah, ikincisi Amarya, üçüncüsü Yahaziel ve dördüncüsü Yekameam."],["20","Uzziel'in oğulları: Baş Mika ve ikincisi İşşiya."],["21","Merari'nin oğulları: Mahli ve Muşi. Mahli'nin oğulları: Eleazar ve Kiş."],["22","Eleazar öldü ve onun oğulları yoktu, sadece kızları vardı; ve onların akrabaları olan Kiş oğulları onları karıları olarak aldılar."],["23","Muşi'nin oğulları: Mahli, Eder ve Yeremot, üç kişi."],["24","Atalar evlerine göre Levioğulları; yirmi yaşında ve ondan yukarı adlarıyla tek tek sayılan atalar evlerinin başları; Yahve'nin evinin hizmeti için iş görenler bunlardı."],["25","Çünkü David, “İsrael'in Tanrısı Yahve halkına rahat verdi; sonsuza dek Yeruşalem'de oturmaktadır” demişti."],["26","“Levililer'in artık çadırı ve onun hizmetinde kullanılan bütün kapları taşımayacaklar.”"],["27","Çünkü David'in son sözleriyle Levioğulları yirmi yaşında ve ondan yukarı olanlar sayıldı."],["28","Çünkü görevleri, Yahve'nin evinin hizmeti için, avlularda, odalarda ve bütün kutsal şeylerin temizlenmesinde, Tanrı evinin hizmetinde Aronoğulları'nın yanında durmak,"],["29","sergi ekmeğine, gerek mayasız yufkaların, gerek sacda pişirilen şeylerin, gerekse yoğrulmuş şeylerin ekmek sunusuna mahsus ince una, her çeşit ölçek ve ölçülere bakmak için;"],["30","her sabah ve akşam da aynı şekilde, Yahve'ye şükretmek ve O'nu övmek için durmak;"],["31","Şabatlar'da, yeni aylarda ve belli bayramlarda, bütün yakmalık sunuları sayısı ile, onlar hakkında olan yasaya göre, sürekli olarak Yahve'nin önünde, Yahve'ye sunmaktı;"],["32","Buluşma Çadırı görevini, kutsal yer görevini ve kardeşleri Aronoğulları'nın Yahve'nin evinin hizmetindeki görevini yerine getireceklerdi."]],24:[["1","Aronoğulları'nın bölükleri şunlardı. Aron'un oğulları: Nadav, Avihu, Eleazar ve İtamar."],["2","Ama Nadav ve Avihu babalarından önce öldüler ve çocukları yoktu; bu yüzden Eleazar ve İtamar kâhin olarak hizmet ettiler."],["3","David ve Eleazaroğulları'ndan Sadok ve İtamaroğulları'ndan Ahimelek, onları kendi hizmetlerindeki sıraya göre ayırdı."],["4","Eleazaroğulları'na göre, İtamaroğulları arasında daha fazla baş bulundu; ve şöyle ayrıldılar: Eleazaroğulları'ndan atalar evlerinin başları on altı; ve İtamaroğulları'ndan, ataları evlerine göre sekiz."],["5","Böylece bunlar kura ile taraf tutmadan ayrıldılar; çünkü hem Eleazaroğulları'ndan, hem de İtamaroğulları'ndan kutsal yer için önderler ve Tanrı için önderler vardı;"],["6","Levililer'den Netanel'in oğlu kâtip Şemaya, bunları kralın, beylerin, kâhin Sadok'un, Aviyatar'ın oğlu Ahimelek'in ve kâhinlerin ve Levililer'in atalar evlerinin başları önünde yazdı. Bir atalar evi Eleazar için, bir atalar evi de İtamar için alındı."],["7","İlk kura Yehoyariv'e, ikincisi Yedaya'ya,"],["8","Üçüncüsü Harim'e, dördüncüsü Seorim'e,"],["9","Beşincisi Malkiya'ya, altıncısı Miyamin'e,"],["10","Yedincisi Hakkos'a, sekizincisi Aviya'ya,"],["11","Dokuzuncusu Yeşua'ya, onuncusu Şekanya'ya,"],["12","On birincisi Elyaşiv'e, on ikincisi Yakim'e,"],["13","On üçüncüsü Hupa'ya, on dördüncüsü Yeşevav'a,"],["14","On beşincisi Bilga'ya, on altıncısı İmmer'e,"],["15","On yedincisi Hezir'e, on sekizincisi Hapitsets'e,"],["16","On dokuzuncusu Petahya'ya, yirmincisi Yehezkel'e,"],["17","Yirmi birincisi Yakin'e, yirmi ikincisi Gamul'a,"],["18","Yirmi üçüncüsü Delaya'ya, yirmi dördüncüsü Maaziya'ya çıktı."],["19","Bu, İsrael'in Tanrısı Yahve'nin kendisine buyurmuş olduğu gibi, ataları Aron'un kendilerine verdiği kurala göre, Yahve'nin evine girmeleri için onların hizmet sırasıydı."],["20","Levi'nin geri kalan oğullarına gelince: Amram'ın oğullarından Şuvael; Şuvael'in oğullarından Yehdeya."],["21","Rehavya'dan: Rehavya'nın oğullarından, baş İşşiya."],["22","Yitshariler'den Şelomot; Şelomot'un oğullarından Yahat."],["23","Hevron'un oğulları: Yeriah, ikinci Amarya, üçüncü Yahaziel ve dördüncü Yekameam."],["24","Uzziel'in oğulları: Mika; Mikaoğulları'ndan Şamir."],["25","Mika'nın kardeşi: İşşiya; İşşiya'nın oğullarından Zekariya."],["26","Merari'nin oğulları: Mahli ve Muşi. Yaaziya'nın oğlu: Beno."],["27","Merari'nin Yaaziya'dan olan oğulları: Beno, Şoham, Zakkur ve İbri."],["28","Mahli'den: Oğlu olmayan Eleazar."],["29","Kiş'den, Kiş'in oğulları: Yerahmeel."],["30","Muşi'nin oğulları: Mahli, Eder ve Yerimot. Bunlar ata evlerine göre Levililer'in oğullarıydı."],["31","Bunlar da kardeşleri Aronoğulları gibi, Kral David'in, Sadok'un, Ahimelek'in ve kâhinlerin ve Levililer'in ata evlerinin başlarının önünde, atalar evlerinin başları küçük kardeşleri gibi kura çektiler."]],25:[["1","David ve ordu komutanları, Asaf'ın, Heman'ın ve Yedutu'nun oğullarından bazılarını, çenklerle, telli çalgılar ve zillerle peygamberlik etmek üzere hizmet için ayırdılar. Hizmetlerine göre işi yapanların sayısı şöyleydi:"],["2","Asafoğulları'ndan: Zakkur, Yosef, Netanya ve Aşarela. Asaf'ın oğulları, kralın buyruğuna göre peygamberlik eden Asaf'ın eli altındaydı."],["3","Yedutun'dan, Yedutoğulları: Gedalya, Zeri, Yeşaya, Şimei, Haşavya ve Mattitya, Yahve'ye şükredip övgüler sunarak çenkle peygamberlik eden babaları Yedutun'un eli altında altı kişiydi."],["4","Heman'dan, Heman'ın oğulları: Bukkiya, Mattanya, Uzziel, Şevuel, Yerimot, Hananya, Hanani, Eliyata, Giddalti, Romamti Ezer, Yoşvekaşah, Malloti, Hotir ve Mahaziot."],["5","Bunların hepsi, boynuzu kaldırmak için, Tanrı'nın sözlerinde kralın göreni olan Heman'ın oğullarıydı. Tanrı, Heman'a on dört oğul ve üç kız verdi."],["6","Onların hepsi, zillerle, telli çalgılarla ve çenklerle, Tanrı evinin hizmeti için, babalarının eli altında, Yahve'nin evinde ezgi söylemek içindiler: Asaf, Yedutun ve Heman, kralın buyruğu altındaydılar."],["7","Bunların sayısı, Yahve'ye ezgi söylemekte eğitilmiş kardeşleriyle birlikte, becerikli olanların hepsi, iki yüz seksen sekizdi."],["8","Küçük büyük, öğretmen öğrenci ayrımı yapılmaksızın, görevleri için kura çektiler."],["9","İlk kura Asaf'a, Yosef'e çıktı; ikincisi Gedalya'ya, kendisi ve kardeşleriyle oğulları on iki;"],["10","üçüncüsü Zakkur'a, oğulları ve kardeşleri on iki;"],["11","dördüncüsü İzri'ye, oğulları ve kardeşleri on iki;"],["12","Beşincisi, Netanya'ya, oğulları ve kardeşleri on iki;"],["13","altıncısı Bukkiya'ya, oğulları ve kardeşleri on iki;"],["14","yedincisi, Yeşarela'ya, oğulları ve kardeşleri on iki;"],["15","sekizincisi, Yeşaya'ya, oğulları ve kardeşleri on iki;"],["16","dokuzuncusu Mattanya'ya, oğulları ve kardeşleri on iki;"],["17","onuncusu Şimei'ye, oğulları ve kardeşleri on iki;"],["18","on birincisi Azarel'e, oğulları ve kardeşleri on iki;"],["19","on ikincisi Haşavya'ya, oğulları ve kardeşleri, on iki;"],["20","on üçüncüsü Şubael'e, oğulları ve kardeşleri, on iki;"],["21","on dördüncüsü Mattitya'ya, oğulları ve kardeşleri, on iki;"],["22","on beşincisi Yeremot'a, oğulları ve kardeşleri, on iki;"],["23","on altıncısı Hananya'ya, oğulları ve kardeşleri, on iki;"],["24","on yedincisi Yoşvekaş'a, oğulları ve kardeşleri, on iki;"],["25","on sekizinci Hanani'ye, oğulları ve kardeşleri, on iki;"],["26","on dokuzuncusu Malloti'ye, oğulları ve kardeşleri, on iki;"],["27","yirmincisi Eliata'ya, oğulları ve kardeşleri, on iki;"],["28","yirmi birincisi Hotir'e, oğulları ve kardeşleri, on iki;"],["29","yirmi ikincisi Giddalti'ye, oğulları ve kardeşleri, on iki;"],["30","yirmi üçüncüsü Mahaziot'a, oğulları ve kardeşleri on iki;"],["31","yirmi dördüncüsü Romamti Ezer'e, oğulları ve kardeşleri on iki."]],26:[["1","Kapı bekçilerinin bölükleri: Korahlılar'dan, Asafoğulları'ndan Kore'nin oğlu Meşelemya."],["2","Meşelemya'nın oğulları: İlk oğlu Zekariya, ikincisi Yediael, üçüncüsü Zevadya, dördüncüsü Yatniel,"],["3","Beşincisi Elam, altıncısı Yehohanan ve yedincisi Elihoenay."],["4","Oved Edom'un oğulları: İlk oğlu Şemaya, ikincisi Yehozavad, üçüncüsü Yoah, dördüncüsü Sakar, beşincisi Netanel,"],["5","altıncısı Ammiel, yedincisi İssakar ve sekizincisi Peulletay; çünkü Tanrı onu kutsamıştı."],["6","Babalarının evini yöneten onun oğlu Şemaya'nın da oğulları oldu; çünkü onlar cesur yiğitlerdi."],["7","Şemaya'nın oğulları: Otni, Refael, Oved ve Elzavad; akrabaları yiğit adamlardı, Elihu ve Semakya."],["8","Bunların hepsi Oved Edomoğulları'ndan, bunlar oğullar ve kardeşleri, hizmet için güçte yiğit adamlardı: Oved Edom'dan altmış iki kişi."],["9","Meşelemya'nın oğulları ve kardeşleri, yiğit adamlar, on sekiz kişi."],["10","Merari'nin çocuklarından Hosa'nın da oğulları vardı: Baş Şimri (ilk doğan olmamasına rağmen babası onu baş yaptı),"],["11","ikincisi Hilkiya, üçüncüsü Tevalya ve dördüncüsü Zekariya. Hosa'nın bütün oğulları ve kardeşleri on üç kişi."],["12","Yahve'nin evinde hizmet etmek için, kardeşleri gibi olan kapı bekçileri bölükleri bunlardan, baş adamlardı."],["13","Her kapı için, atalar evlerine göre, küçüğü de büyüğü de kura çektiler."],["14","Doğuya doğru kura Şelemya'ya düştü. Sonra bilge bir danışman olan oğlu Zekariya için kura çektiler; ve onun kurası kuzeye çıktı."],["15","Oved Edom'a güneye; ve oğullarına ambar evine."],["16","Şuppim ve Hosa'ya batıya, Şalleket Kapısı yanında, yukarı çıkan geçitte, karşılıklı iki nöbet yerine çıktı."],["17","Doğuya doğru altı Levili, kuzeye günde dört, güneye günde dört ve ambar için ikişer ikişer."],["18","Batıya doğru Parbar için, geçitte dört ve Parbar'da iki."],["19","Kapı bekçilerinin bölükleri şunlardı: Korahlılar'ın oğulları ve Merarililer'in oğulları."],["20","Levililer'den Ahiya, Tanrı evinin hazinelerinin ve adanmış şeylerin hazinelerinin başındaydı."],["21","Ladanoğulları, Ladan'a ait Gerşonlular'ın oğulları, Ladan'a ait ata evlerinin başları Gerşonlu Yehieli."],["22","Yehieli’nin oğulları: Zetam ve kardeşi Yoel, Yahve'nin evinin hazinelerinin başındaydılar."],["23","Amramlılar'dan, Yitsharlılar'dan, Hebronlular'dan, Uzzielliler'den:"],["24","Moşe’nin oğlu Gerşom’un oğlu Şevuel hazinelerin yöneticisiydi."],["25","Kardeşleri: Eliezer’den, oğlu Rehavya, onun oğlu Yeşaya, onun oğlu Yoram, onun oğlu Zikri ve onun oğlu Şelomot."],["26","Bu Şelomot ve kardeşleri, Kral David’in ve atalar evlerinin başlarının, binlerin ve yüzlerin komutanlarının ve ordu komutanlarının adadığı bütün hazinelerin başındaydılar."],["27","Savaşlarda kazanılan ganimetlerden bazılarını Yahve'nin evini onarmak için adadılar."],["28","Gören Samuel'in, Kiş oğlu Saul'un, Ner oğlu Avner'in ve Seruya oğlu Yoav'ın adadığı her şey, kim bir şey adamışsa, Şelomot'un ve kardeşlerinin eli altındaydı."],["29","Yitsharlılar'dan Kenanya ve oğulları, İsrael üzerine memurlar ve hâkimler olarak dışarıdaki işlere bakmak üzere atandılar."],["30","Hevronlular'dan Haşavya ve kardeşleri, bin yedi yüz yiğit adam, Yahve'nin bütün işlerini ve kralın hizmetini, Yarden'in ötesinde batıya doğru İsrael'in gözetimini üstlendi."],["31","Hevronlular'dan Yeriyah, ataları evlerinin kuşaklarına göre Hevronlular'ın başıydı. David'in krallığının kırkıncı yılında arandılar ve Gilad'ın Yatser Kenti'nde onların arasında cesur yiğitler bulundu."],["32","Akrabaları yiğit adamlardı; atalar evlerinin başları olan iki bin yedi yüz kişiydiler. Kral David, Tanrı'yla ilgili her iş için ve kralın işleri için Ruvenliler, Gadlılar ve Manaşşeliler'in yarım oymağı üzerinde onları gözetmenler olarak atadı."]],27:[["1","İsrael'in çocukları, sayılarına göre, atalar evlerinin başları, binlerin ve yüzlerin başları ve yılın bütün aylarında krala her ay girip çıkan bölüklerde hizmet eden memurları, her bölüğün yirmi dört bin kişisi vardı."],["2","Birinci ay için, birinci bölüğün başında Zavdiel oğlu Yaşoveam vardı. Onun bölüğünde yirmi dört bin kişi vardı."],["3","Kendisi Peres'in çocuklarındandı, birinci ay için bütün ordu komutanlarının başıydı."],["4","İkinci ayın bölüğü başında Ahohlu Doday vardı, onun bölüğünde önder Miklot'du; onun bölüğünde yirmi dört bin kişi vardı."],["5","Üçüncü ay için üçüncü ordu komutanı, başkâhin Yehoyada'nın oğlu Benaya'ydı. Onun bölüğünde yirmi dört bin kişi vardı."],["6","Otuzlar'ın yiğidi ve Otuzlar'ın başında olan Benaya budur. Onun bölüğünde oğlu Ammizavad vardı."],["7","Dördüncü ay için dördüncü komutan Yoav'ın kardeşi Asahel ve kendisinden sonra oğlu Zevadya'ydı. Onun bölüğünde yirmi dört bin kişi vardı."],["8","Beşinci ay için beşinci komutan İzrahlı Şamhut'tu. Onun bölüğünde yirmi dört bin kişi vardı."],["9","Altıncı ay için altıncı komutan Tekolu İkkeş'in oğlu İra'ydı. Onun bölüğünde yirmi dört bin kişi vardı."],["10","Yedinci ay için yedinci komutan Efraim'in çocuklarından Pelonlu Heles'ti. Onun bölüğünde yirmi dört bin kişi vardı."],["11","Sekizinci ay için sekizinci komutan Zerahlılar'dan Huşalı Sivvekay'dı. Onun bölüğünde yirmi dört bin kişi vardı."],["12","Dokuzuncu ay için dokuzuncu komutan Benyaminliler'den Anatotlu Aviezer'di. Onun bölüğünde yirmi dört bin kişi vardı."],["13","Onuncu ay için onuncu komutan Zerahlılar'dan Netofalı Maharay'dı. Onun bölüğünde yirmi dört bin kişi vardı."],["14","On birinci ay için on birinci komutan, Efraim'in çocuklarından Piratonlu Benaya'ydı. Onun bölüğünde yirmi dört bin kişi vardı."],["15","On ikinci ay için on ikinci komutan, Otniel'den Netofalı Helday'dı. Onun bölüğünde yirmi dört bin kişi vardı."],["16","İsrael oymaklarının başında da şunlar vardı: Ruvenliler'den baş Zikri'nin oğlu Eliezer; Şimonlular'dan Maaka'nın oğlu Şefatya;"],["17","Levi'den Kemuel'in oğlu Haşavya; Aron'dan Sadok;"],["18","Yahuda'dan David'in kardeşlerinden Elihu; İssakar'dan Mikael'in oğlu Omri;"],["19","Zevulun'dan Ovadya oğlu İşmaya; Naftalililer'den Azriel'in oğlu Yeremot;"],["20","Efraim'in çocuklarından Azaziya'nın oğlu Hoşea; Manaşşe'nin yarım oymağından, Pedaya oğlu Yoel;"],["21","Gilad'daki Manaşşe'nin yarım oymağından, Zekariya oğlu İddo; Benyamin'den Avner'in oğlu Yaasiel;"],["22","Dan'dan Yeroham'ın oğlu Azarel. Bunlar İsrael oymaklarının komutanlarıydı."],["23","Ancak David yirmi yaş ve altındakilerin sayısını almadı. Çünkü Yahve İsrael'i gökyüzünün yıldızları gibi çoğaltacağını söylemişti."],["24","Seruya oğlu Yoav sayım yapmaya başladı, ama bitirmedi. Bunun üzerine İsrael üzerine gazap geldi. Sayı Kral David'in Tarihler Kitabı'nda hesaba konulmadı."],["25","Kralın hazinelerinin başında Adiel oğlu Azmavet vardı. Kırlardaki, kentlerdeki, köylerdeki ve kulelerdeki hazinelerin başında Uzziya oğlu Yonatan vardı."],["26","Tarlada çalışıp toprağı sürenlerin başında Keluv oğlu Ezri vardı."],["27","Bağların başında Ramalı Şimei vardı. Şarap mahzenleri için bağların ürünü başında Şifamlı Zavdi vardı."],["28","Ovadaki zeytin ağaçlarının ve yabanıl incir ağaçlarının başında Gedeli Baal Hanan vardı. Yağ mahzenlerinin başı Yoaş'tı."],["29","Şaron'da otlayan sürülerin başında Şaronlu Şitray vardı. Vadilerdeki sürülerin başında Adlay oğlu Şafat vardı."],["30","Develerin başında İşmaelli Ovil vardı. Eşeklerin başında Meronotlu Yehdeya vardı. Sürülerin başında Hagritli Yaziz vardı."],["31","Bütün bunlar Kral David'in mülkünün yöneticileriydi."],["32","David'in amcası Yonatan da danışman, anlayışlı bir adam ve yazıcıydı. Hakmoni'nin oğlu Yehiel kralın oğullarıyla birlikteydi."],["33","Kralın danışmanı Ahitofel'di. Kralın dostu Arklı Huşay'dı."],["34","Ahitofel'den sonra Benaya'nın oğlu Yehoyada ve Aviyatar vardı. Kralın ordusunun başkomutanı Yoav'dı."]],28:[["1","David, İsrael'in bütün beylerini, oymak beylerini, krala bölük bölük hizmet eden birlik komutanlarını, binlerin başlarını, yüzlerin başlarını ve kralın ve oğullarının bütün malının ve mülklerinin yöneticilerini, subayları ve yiğitleri, bütün cesur yiğitleri Yeruşalem'e topladı."],["2","O zaman Kral David ayağa kalkıp şöyle dedi: “Ey kardeşlerim ve halkım beni dinleyin! Ben, Yahve'nin Antlaşma Sandığı için ve Tanrımız'ın ayaklarının basamağı için bir dinlenme evi yapmak yüreğimdeydi. Onun için hazırlık da yapmıştım."],["3","Ama Tanrı bana, 'Adım için bir ev yapmayacaksın, çünkü sen savaş adamısın ve kan döktün' dedi."],["4","Ancak İsrael'in Tanrısı Yahve, İsrael üzerine daima kral olmak için babamın bütün evinden beni seçti; çünkü hükümdar olarak Yahuda'yı, Yahuda evinden de babamın evini seçti; ve bütün İsrael üzerine babamın oğulları arasında beni kral yapmaktan hoşnut oldu."],["5","Bütün oğullarım arasından (çünkü Yahve bana birçok oğul verdi), İsrael üzerinde Yahve'nin krallığının tahtına oturması için oğlum Solomon'u seçti."],["6","Bana şöyle dedi, 'Oğlun Solomon evimi ve avlularımı yapacak; çünkü onu oğlum olarak seçtim ben de onun babası olacağım."],["7","Bugün olduğu gibi, buyruklarımı ve kurallarımı yerine getirmeyi sürdürürse, onun krallığını daima pekiştireceğim.'"],["8","Şimdi, bütün İsrael'in gözü önünde, Yahve'nin topluluğu önünde ve Tanrımız duyarken, Tanrınız Yahve'nin bütün buyruklarını tutun ve araştırın ki, bu güzel ülkeyi mülk olarak edinesiniz ve onu daima sizden sonraki çocuklarınıza miras olarak bırakasınız."],["9","Sen, oğlum Solomon, babanın Tanrısı'nı tanı ve ona tam bir yürekle ve istekli bir düşünceyle hizmet et; çünkü Yahve bütün yürekleri araştırır ve düşüncelerin bütün hayal ettiği şeyleri anlar. Eğer onu ararsan, sana kendisini buldurur; ama eğer onu bırakırsan, seni sonsuza dek atar."],["10","Şimdi dikkat et, çünkü kutsal yer için ev yapmak üzere Yahve seni seçti. Güçlü ol ve yap.”"],["11","Sonra David, oğlu Solomon'a tapınağın eyvanla evlerinin, hazinelerinin, üst odalarının, iç odalarının, merhamet yerinin planlarını verdi;"],["12","Yahve'nin evinin avluları, çevredeki bütün odalar, Tanrı evinin hazineleri ve adanmış şeylerin hazineleri için;"],["13","kâhinlerin ve Levililer'in takımları için, Yahve'nin evinin hizmetinin bütün işi için, Yahve'nin evindeki bütün hizmet kapları için,"],["14","altın kaplar için, tartısına göre altından, her türlü hizmetin bütün kapları için, bütün gümüş kaplar için, tartısına göre gümüşten her türlü hizmetin bütün kapları için, Ruh aracılığıyla sahip olduğu her şeyin planlarını verdi."],["15","Her şamdanla ve onun kandillerinin tartısına göre, altın şamdanların ve kandillerinin tartısını; ve her şamdanın hizmetine göre gümüş şamdanlar için, her bir şamdanın ve kandillerinin tartısına göre onları da tartsın;"],["16","ve sergi ekmeği masaları için, her masa için altın; ve gümüş masalar için gümüş tartısını;"],["17","ve saf altından çatallarının, leğenlerin ve kâselerin tartısını; ve altın taslar için, her tasın tartısını, gümüş taslar için, her tasın tartısını;"],["18","ve buhur sunağı için, saf altının tartısını; ve kanatlarını yapıp Yahve'nin Antlaşma Sandığı'nı örten Keruvlar arabasının planlarına göre altın tartısını verdi."],["19","David, “Bütün bunlar,” dedi, “Bu örneğin bütün işleri, Yahve'nin elinden bana yazılı olarak anlatıldı.”"],["20","David oğlu Solomon'a, “Güçlü ve cesur ol, yap” dedi, “Korkma, yılma, çünkü Yahve Tanrı, benim Tanrım seninle birliktedir. Yahve'nin evinin hizmeti için bütün iş bitinceye dek seni başarısızlığa uğratmayacak, seni bırakmayacaktır."],["21","İşte, Tanrı'nın evinin bütün hizmeti için kâhinlerin ve Levililer'in bölükleri var. Her türlü hizmette, becerikli olan her istekli adam her türlü işte seninle birlikte olacak. Komutanlar ve bütün halk da tümüyle senin buyruğunda olacak.”"]],29:[["1","Kral David bütün topluluğa şöyle dedi: “Tanrı'nın tek seçtiği oğlum Solomon henüz genç ve toydur; yapılacak iş de büyüktür. Çünkü bu saray insan için değil, Tanrı Yahve içindir."],["2","Şimdi Tanrım'ın evi için bütün gücümle altın şeyler için altın, gümüş şeyler için gümüş, tunç şeyler için tunç, demir şeyler için demir, ağaç şeyler için ağaç, ayrıca oniks taşları, kakma taşlar, ziynet taşları, çeşitli renkli taşlar, her türlü değerli taşlar ve bol miktarda mermer taşları da hazırladım."],["3","Bundan başka, Tanrım'ın evini sevdiğim için, madem ki kendi altın ve gümüş hazinem vardır, kutsal ev için hazırladığım her şeyden daha fazlasını Tanrım'ın evine,"],["4","Ofir altınından üç bin talant altını ve evlerin duvarlarını kaplamak için yedi bin talant saf gümüşü;"],["5","altın şeyler için altını, gümüş şeyler için gümüşü ve zanaatkârların elleriyle yapılacak her türlü işler için veriyorum. Öyleyse kim bugün gönüllü olarak kendini Yahve'ye adıyor?”"],["6","Atalar evlerinin beyleri, İsrael oymaklarının beyleri, binlerin ve yüzlerin komutanları, kralın işlerinin yöneticileriyle birlikte gönülden sundular."],["7","Tanrı'nın evinin hizmeti için beş bin talant altın, on bin darik, on bin talant gümüş, on sekiz bin talant tunç ve yüz bin talant demir verdiler."],["8","Kendilerinde değerli taşlar bulunanlar, Gerşonlu Yehiel'in eliyle Yahve'nin evinin hazinesine verdiler."],["9","O zaman halk sevindi, çünkü gönülden sunmuşlardı, çünkü bütün yürekle Yahve'ye gönülden sundular. Kral David de büyük bir sevinçle sevindi."],["10","Bunun üzerine David bütün topluluğun önünde Yahve'yi övdü. David, “Ey Yahve, atamız İsrael'in Tanrısı, sen sonsuzluklar boyunca yücesin” dedi."],["11","“Ey Yahve, büyüklük, güç, görkem, zafer ve heybet senindir! Çünkü göklerde ve yerde olan her şey senindir. Ey Yahve, krallık senindir ve sen baş olarak her şeyden yükseksin."],["12","Zenginlik ve onur senden gelir ve sen her şeye hakimsin! Güç ve kudret senin elindedir! Büyük kılmak ve herkesi güçlendirmek senin elindedir!"],["13","Şimdi, ey Tanrımız, biz sana şükrederiz ve görkemli adını överiz."],["14","Ama ben kimim ve halkım nedir ki, böyle gönülden sunabilelim? Çünkü her şey senden gelir ve biz sana seninkilerden verdik."],["15","Çünkü biz senin önünde yabancıyız ve bütün atalarımız gibi misafiriz. Yeryüzündeki günlerimiz bir gölge gibidir, geriye bir şey kalmaz."],["16","Ey Tanrımız Yahve, kutsal adına bir ev yapmak için hazırladığımız bütün bu hazine senin elinden gelmiştir ve hepsi senindir."],["17","Ey Tanrım, yüreği sınadığını ve doğruluktan hoşlandığını da biliyorum. Bense yüreğimin doğruluğuyla bütün bunları gönülden sundum. Şimdi burada bulunan halkının sana gönülden sunduğunu sevinçle gördüm."],["18","Atalarımız Avraham'ın, İshak'ın ve İsrael'in Tanrısı ey Yahve, bu isteği daima halkının yüreğinin düşüncelerinde tut ve onların yüreğini kendine hazırla;"],["19","oğlum Solomon'a da senin buyruklarını, tanıklıklarını ve kurallarını tutmak için, bütün bu şeyleri yapmak için ve hazırlığını yaptığım sarayı bina etmek için bütün bir yürek ver.”"],["20","Sonra David bütün topluluğa, “Şimdi Tanrınız Yahve'yi övün!” dedi. Bütün topluluk atalarının Tanrısı Yahve'yi övdüler ve başlarını eğip Yahve'nin ve kralın önünde yere kapandılar."],["21","Yahve'ye kurbanlar kestiler ve o günün ertesi gün Yahve'ye yakmalık sunular sundular; bin boğa, bin koç ve bin kuzu, onların dökmelik sunularını, bütün İsrael için bol miktarda kurbanlar sundular."],["22","O gün büyük bir sevinçle Yahve'nin önünde yiyip içtiler. David oğlu Solomon'u ikinci kez kral yaptılar ve onu Yahve'nin önünde hükümdar, Sadok'u da kâhin olarak meshettiler."],["23","O zaman Solomon babası David'in yerine Yahve'nin tahtına oturdu ve başarılı oldu; bütün İsrael ona itaat etti."],["24","Bütün beyler, yiğitler ve Kral David'in bütün oğulları Kral Solomon'a boyun eğdiler."],["25","Yahve, Solomon'u bütün İsrael'in gözünde çok büyüttü, İsrael'de kendisinden önce hiçbir kralın üzerinde olmayan krallık yüceliğini ona verdi."],["26","Yişay oğlu David bütün İsrael üzerinde hüküm sürdü."],["27","İsrael'de kırk yıl hüküm sürdü; Hevron'da yedi yıl hüküm sürdü, Yeruşalem'de de otuz üç yıl hüküm sürdü."],["28","Güzel ihtiyarlıkta, günlere, zenginliğe ve onura doymuş olarak öldü; ve oğlu Solomon onun yerine kral oldu."],["29","Kral David'in işleri, ilk ve son işleri, işte bunlar, gören Samuel'in tarihinde, Peygamber Natan'ın tarihinde ve gören Gad'ın tarihinde,"],["30","onun bütün krallığı ve kudreti, İsrael ve bütün ülkelerdeki krallıkların dahil olduğu olaylarla birlikte yazılıdır."]]};export{a as default};
